enum class V2XBehaviorState
{
  Cruise,
  Follow,
  Overtake,
  LowSpeedAvoidance,
  SafetyBrake,
};

const char * to_string(const V2XBehaviorState state)
{
  switch (state) {
    case V2XBehaviorState::Cruise:
      return "Cruise";
    case V2XBehaviorState::Follow:
      return "Follow";
    case V2XBehaviorState::Overtake:
      return "Overtake";
    case V2XBehaviorState::LowSpeedAvoidance:
      return "LowSpeedAvoidance";
    case V2XBehaviorState::SafetyBrake:
      return "SafetyBrake";
  }
  return "Unknown";
}

enum class OvertakeLinePhase
{
  Idle,
  FollowPrepare,
  ShiftOut,
  Pass,
  Return,
  Recovery,
};

overtake_orchestrator::Phase orchestrator_phase(const OvertakeLinePhase phase)
{
  switch (phase) {
    case OvertakeLinePhase::Idle:
      return overtake_orchestrator::Phase::Idle;
    case OvertakeLinePhase::FollowPrepare:
      return overtake_orchestrator::Phase::FollowPrepare;
    case OvertakeLinePhase::ShiftOut:
      return overtake_orchestrator::Phase::ShiftOut;
    case OvertakeLinePhase::Pass:
      return overtake_orchestrator::Phase::Pass;
    case OvertakeLinePhase::Return:
      return overtake_orchestrator::Phase::Return;
    case OvertakeLinePhase::Recovery:
      return overtake_orchestrator::Phase::Recovery;
  }
  return overtake_orchestrator::Phase::Idle;
}

OvertakeLinePhase overtake_line_phase(const overtake_orchestrator::Phase phase)
{
  switch (phase) {
    case overtake_orchestrator::Phase::Idle:
      return OvertakeLinePhase::Idle;
    case overtake_orchestrator::Phase::FollowPrepare:
      return OvertakeLinePhase::FollowPrepare;
    case overtake_orchestrator::Phase::ShiftOut:
      return OvertakeLinePhase::ShiftOut;
    case overtake_orchestrator::Phase::Pass:
      return OvertakeLinePhase::Pass;
    case overtake_orchestrator::Phase::Return:
      return OvertakeLinePhase::Return;
    case overtake_orchestrator::Phase::Recovery:
      return OvertakeLinePhase::Recovery;
  }
  return OvertakeLinePhase::Idle;
}

std::optional<overtake_orchestrator::Phase> overtake_phase_for_intent(
  const mpcc_contract::ControlIntent intent)
{
  switch (intent) {
    case mpcc_contract::ControlIntent::ShiftOut:
      return overtake_orchestrator::Phase::ShiftOut;
    case mpcc_contract::ControlIntent::Pass:
      return overtake_orchestrator::Phase::Pass;
    case mpcc_contract::ControlIntent::Return:
      return overtake_orchestrator::Phase::Return;
    default:
      return std::nullopt;
  }
}

overtake_orchestrator::Behavior orchestrator_behavior(
  const V2XBehaviorState state)
{
  switch (state) {
    case V2XBehaviorState::Cruise:
      return overtake_orchestrator::Behavior::Cruise;
    case V2XBehaviorState::Follow:
      return overtake_orchestrator::Behavior::Follow;
    case V2XBehaviorState::Overtake:
      return overtake_orchestrator::Behavior::Overtake;
    case V2XBehaviorState::LowSpeedAvoidance:
      return overtake_orchestrator::Behavior::LowSpeedAvoidance;
    case V2XBehaviorState::SafetyBrake:
      return overtake_orchestrator::Behavior::SafetyBrake;
  }
  return overtake_orchestrator::Behavior::Cruise;
}

enum class FollowPrepareCause
{
  Unspecified,
  SafetyBrake,
  DynamicMissionWait,
  TacticalRevalidation,
  RecoveryRetention,
};

enum class ReturnReacquirePolicy
{
  /// A newly available same-target/same-side corridor may cancel an early Return.
  SameTargetEarly,
  /// The tactical owner deliberately relinquished Pass; finish Return before
  /// evaluating the target as a new Mission.
  FinishReturn,
};

enum class V2XTrackingResetPolicy
{
  PreserveHistory,
  ClearHistory,
};

const char * to_string(const OvertakeLinePhase phase)
{
  switch (phase) {
    case OvertakeLinePhase::Idle:
      return "Idle";
    case OvertakeLinePhase::FollowPrepare:
      return "FollowPrepare";
    case OvertakeLinePhase::ShiftOut:
      return "ShiftOut";
    case OvertakeLinePhase::Pass:
      return "Pass";
    case OvertakeLinePhase::Return:
      return "Return";
    case OvertakeLinePhase::Recovery:
      return "Recovery";
  }
  return "Unknown";
}

bool is_overtake_target_interaction_phase(const OvertakeLinePhase phase)
{
  return phase == OvertakeLinePhase::ShiftOut || phase == OvertakeLinePhase::Pass;
}

bool is_overtake_receding_horizon_execution_phase(const OvertakeLinePhase phase)
{
  return is_overtake_target_interaction_phase(phase) ||
         phase == OvertakeLinePhase::Return;
}

bool is_solved_overtake_trajectory_handoff_compatible(
  const OvertakeLinePhase source, const OvertakeLinePhase current)
{
  if (
    !is_overtake_receding_horizon_execution_phase(source) ||
    !is_overtake_receding_horizon_execution_phase(current))
  {
    return false;
  }
  return source == current ||
         (source == OvertakeLinePhase::ShiftOut && current == OvertakeLinePhase::Pass) ||
         (source == OvertakeLinePhase::Pass && current == OvertakeLinePhase::Return);
}

bool is_published_overtake_execution_handoff_phase(
  const OvertakeLinePhase phase)
{
  // Tactical phase may advance before canonical atomic admission publishes the
  // successor. Keep querying the executed ledger across that boundary while
  // requiring an exact phase-compatible intent, target, generation, side,
  // immutable source time, and a live publication cursor.
  return phase == OvertakeLinePhase::ShiftOut ||
         phase == OvertakeLinePhase::Pass;
}

const char * to_string(const FollowPrepareCause cause)
{
  switch (cause) {
    case FollowPrepareCause::Unspecified:
      return "Unspecified";
    case FollowPrepareCause::SafetyBrake:
      return "SafetyBrake";
    case FollowPrepareCause::DynamicMissionWait:
      return "DynamicMissionWait";
    case FollowPrepareCause::TacticalRevalidation:
      return "TacticalRevalidation";
    case FollowPrepareCause::RecoveryRetention:
      return "RecoveryRetention";
  }
  return "Unknown";
}

bool is_tactical_rolling_replan_cause(const FollowPrepareCause cause)
{
  switch (cause) {
    case FollowPrepareCause::DynamicMissionWait:
    case FollowPrepareCause::TacticalRevalidation:
    case FollowPrepareCause::RecoveryRetention:
      return true;
    case FollowPrepareCause::Unspecified:
    case FollowPrepareCause::SafetyBrake:
      return false;
  }
  return false;
}

overtake_core::PausedExecutionOrigin paused_execution_origin(
  const OvertakeLinePhase phase)
{
  switch (phase) {
    case OvertakeLinePhase::ShiftOut:
      return overtake_core::PausedExecutionOrigin::ShiftOut;
    case OvertakeLinePhase::Pass:
      return overtake_core::PausedExecutionOrigin::Pass;
    case OvertakeLinePhase::Recovery:
      return overtake_core::PausedExecutionOrigin::Recovery;
    case OvertakeLinePhase::Idle:
    case OvertakeLinePhase::FollowPrepare:
    case OvertakeLinePhase::Return:
      return overtake_core::PausedExecutionOrigin::None;
  }
  return overtake_core::PausedExecutionOrigin::None;
}

int behavior_restriction_rank(const V2XBehaviorState state)
{
  switch (state) {
    case V2XBehaviorState::Cruise:
      return 0;
    case V2XBehaviorState::Overtake:
      return 1;
    case V2XBehaviorState::Follow:
      return 2;
    case V2XBehaviorState::LowSpeedAvoidance:
      return 3;
    case V2XBehaviorState::SafetyBrake:
      return 4;
  }
  return 0;
}

