/// Atomic admission handoff at the real Overtake Gate-A boundary.
/// Mission geometry and the causal six-state proof must travel together; a
/// caller may not reconstruct either half from an older tactical result.
struct RateResolvedMissionGateAProposal
{
  std::uint64_t sequence{};
  std::uint64_t context_epoch{};
  std::uint64_t tactical_source_sequence{};
  std::uint64_t prospective_mission_generation{};
  std::uint64_t target_obstacle_generation{};
  std::string target_id;
  int selected_side_sign{};
  overtake_core::OvertakeMissionCandidate mission;
  std::shared_ptr<const rate_resolved_certified::CertifiedPlan> certified_plan;

  bool complete() const noexcept
  {
    return sequence != 0U && context_epoch != 0U &&
           tactical_source_sequence != 0U &&
           prospective_mission_generation != 0U && !target_id.empty() &&
           target_obstacle_generation != 0U &&
           (selected_side_sign == -1 || selected_side_sign == 1) &&
           mission.pass_side_sign == selected_side_sign &&
           mission.physical_execution_certificate_valid &&
           race_mpcc::exact_physical_execution_trajectory_complete(
             mission.physical_execution_certificate_exact_trajectory) &&
           certified_plan != nullptr &&
           certified_plan->execution_artifact != nullptr &&
           certified_plan->execution_artifact->identity.source_context.
           target_obstacle_generation == target_obstacle_generation &&
           certified_plan->execution_artifact->identity.source_context.
           execution_side_sign == selected_side_sign;
  }
};

struct RateResolvedReturnGateAProposal
{
  std::uint64_t sequence{};
  std::uint64_t context_epoch{};
  std::uint64_t mission_generation{};
  std::uint64_t target_obstacle_generation{};
  std::string target_id;
  int side_sign{};
  bool current_world_certified{false};
  std::shared_ptr<const rate_resolved_certified::CertifiedPlan> certified_plan;

  bool complete() const noexcept
  {
    if (
      sequence == 0U || context_epoch == 0U || mission_generation == 0U ||
      target_obstacle_generation == 0U || target_id.empty() ||
      (side_sign != -1 && side_sign != 1) || !current_world_certified ||
      certified_plan == nullptr || certified_plan->execution_artifact == nullptr)
    {
      return false;
    }
    const auto & source_context =
      certified_plan->execution_artifact->identity.source_context;
    return
      source_context.intent == mpcc_contract::ControlIntent::Return &&
      source_context.intent_generation == mission_generation &&
      source_context.target_id == target_id &&
      source_context.target_obstacle_generation ==
      target_obstacle_generation &&
      source_context.execution_side_sign == side_sign;
  }
};

