struct V2XGapPlanner
{
  struct TrackedVehicle
  {
    std::string id;
    double x{};
    double y{};
    double covariance_x{};
    double covariance_y{};
    double stamp_sec{};
    double receipt_sec{};
    double vx{};
    double vy{};
    double ax{};
    double ay{};
    double velocity_observation_interval_sec{};
    std::uint64_t observation_generation{};
    std::uint64_t recovery_epoch{};
    bool recovery_sample_valid{false};
    bool has_sample{false};
    bool position_jump{false};
    bool invalid_velocity{false};
    bool velocity_observation_valid{false};
    bool motion_estimate_valid{false};
  };

  struct LateralInterval
  {
    double lower{};
    double upper{};

    double width() const
    {
      return upper - lower;
    }

    double center() const
    {
      return 0.5 * (lower + upper);
    }
  };

  struct OccupiedInterval
  {
    double lower{};
    double upper{};
    double distance_from_self{};
    std::string lower_vehicle_id;
    std::string upper_vehicle_id;
    double lower_wall_extra_inflation{};
    double upper_wall_extra_inflation{};

    double width() const
    {
      return upper - lower;
    }
  };

  struct GapCandidate
  {
    LateralInterval interval;
    bool lower_is_vehicle{false};
    bool upper_is_vehicle{false};
    double lower_vehicle_distance{std::numeric_limits<double>::infinity()};
    double upper_vehicle_distance{std::numeric_limits<double>::infinity()};
    std::string lower_vehicle_id;
    std::string upper_vehicle_id;
    double lower_vehicle_wall_extra_inflation{};
    double upper_vehicle_wall_extra_inflation{};

    bool is_vehicle_vehicle_gap() const
    {
      return lower_is_vehicle && upper_is_vehicle;
    }

    double nearest_vehicle_distance() const
    {
      return std::min(lower_vehicle_distance, upper_vehicle_distance);
    }
  };

  struct Diagnostics
  {
    std::string health{"NoData"};
    double receipt_age_sec{std::numeric_limits<double>::infinity()};
    double source_age_sec{std::numeric_limits<double>::infinity()};
    double receipt_interval_sec{std::numeric_limits<double>::infinity()};
    std::size_t message_vehicle_count{0U};
    std::size_t fresh_vehicle_count{0U};
    std::size_t position_jump_count{0U};
    std::size_t invalid_velocity_count{0U};
    bool message_invalid{false};
  };

  struct EmptyWorldObservation
  {
    std::uint64_t observation_generation{};
    double receipt_sec{std::numeric_limits<double>::quiet_NaN()};
    std::size_t active_vehicle_count{};
    bool current{false};
  };

  struct DynamicWorldObservation
  {
    std::uint64_t observation_generation{};
    double receipt_sec{std::numeric_limits<double>::quiet_NaN()};
    double source_sec{std::numeric_limits<double>::quiet_NaN()};
    std::vector<TrackedVehicle> vehicles;
    bool current{false};
  };

  explicit V2XGapPlanner(
    const V2XGapPlannerConfig & cfg_in, const bool track_recovery_completeness = false)
  : cfg(cfg_in), track_recovery_completeness_(track_recovery_completeness) {}

  /// Detach the small mutable V2X planning state for a background tactical
  /// rollout. The worker never shares continuity/logging maps with the live
  /// subscriber path, while the immutable reference path remains external.
  std::unique_ptr<V2XGapPlanner> tactical_snapshot()
  {
    std::lock_guard<std::mutex> lock(mutex_);
    auto snapshot = std::make_unique<V2XGapPlanner>(
      cfg, track_recovery_completeness_);
    snapshot->vehicles_ = vehicles_;
    snapshot->last_message_receipt_sec_ = last_message_receipt_sec_;
    snapshot->last_message_receipt_interval_sec_ =
      last_message_receipt_interval_sec_;
    snapshot->last_message_source_stamp_sec_ = last_message_source_stamp_sec_;
    snapshot->last_message_recovery_epoch_ = last_message_recovery_epoch_;
    snapshot->observation_generation_ = observation_generation_;
    snapshot->recovery_epoch_ = recovery_epoch_;
    snapshot->last_message_vehicle_count_ = last_message_vehicle_count_;
    snapshot->last_message_vehicle_ids_ = last_message_vehicle_ids_;
    snapshot->peer_identity_tracker_ = peer_identity_tracker_;
    snapshot->last_message_has_empty_id_ = last_message_has_empty_id_;
    snapshot->last_message_has_duplicate_id_ = last_message_has_duplicate_id_;
    snapshot->last_message_has_invalid_sample_ = last_message_has_invalid_sample_;
    snapshot->last_target_ey_ = last_target_ey_;
    snapshot->low_speed_locked_target_ey_ = low_speed_locked_target_ey_;
    snapshot->low_speed_locked_side_sign_ = low_speed_locked_side_sign_;
    snapshot->last_logged_local_path_side_ = last_logged_local_path_side_;
    snapshot->last_logged_local_path_target_ey_ =
      last_logged_local_path_target_ey_;
    snapshot->last_logged_local_path_corridor_enforced_ =
      last_logged_local_path_corridor_enforced_;
    snapshot->last_logged_course_lateral_motion_sign_ =
      last_logged_course_lateral_motion_sign_;
    return snapshot;
  }

  void update(const V2XVehiclePositionArray & msg, const double receipt_sec)
  {
    std::lock_guard<std::mutex> lock(mutex_);
    ++observation_generation_;
    if (last_message_receipt_sec_.has_value()) {
      const double interval_sec = receipt_sec - last_message_receipt_sec_.value();
      last_message_receipt_interval_sec_ =
        std::isfinite(interval_sec) && interval_sec >= 0.0 ?
        std::optional<double>{interval_sec} : std::nullopt;
    }
    last_message_receipt_sec_ = receipt_sec;
    last_message_vehicle_count_ = msg.vehicles.size();
    last_message_has_empty_id_ = false;
    last_message_has_duplicate_id_ = false;
    last_message_has_invalid_sample_ = false;
    std::unordered_set<std::string> message_ids;
    const double array_stamp = stamp_to_seconds(msg.header.stamp);
    const bool array_header_invalid =
      msg.header.frame_id != "map" ||
      !stuck_recovery::source_timestamp_is_monotonic(
      array_stamp, last_message_source_stamp_sec_);
    if (array_header_invalid) {
      last_message_has_invalid_sample_ = true;
    }
    if (std::isfinite(array_stamp) && array_stamp > 0.0) {
      last_message_source_stamp_sec_ = array_stamp;
    }
    for (const auto & vehicle : msg.vehicles) {
      const bool empty_id = vehicle.vehicle_id.empty();
      const bool duplicate_id =
        !empty_id && !message_ids.emplace(vehicle.vehicle_id).second;
      if (empty_id) {
        last_message_has_empty_id_ = true;
      } else if (duplicate_id) {
        last_message_has_duplicate_id_ = true;
      }
      const bool invalid_geometry =
        !std::isfinite(vehicle.position.x) || !std::isfinite(vehicle.position.y) ||
        !std::isfinite(vehicle.covariance.x) || !std::isfinite(vehicle.covariance.y) ||
        vehicle.covariance.x < 0.0 || vehicle.covariance.y < 0.0 ||
        (!vehicle.header.frame_id.empty() && vehicle.header.frame_id != "map");
      if (invalid_geometry) {
        last_message_has_invalid_sample_ = true;
      }
      const std::string id = vehicle.vehicle_id.empty() ? "__unknown__" : vehicle.vehicle_id;
      double sample_stamp = stamp_to_seconds(vehicle.header.stamp);
      if (sample_stamp <= 0.0) {
        sample_stamp = array_stamp > 0.0 ? array_stamp : receipt_sec;
      }

      auto & tracked = vehicles_[id];
      const bool source_sample_invalid =
        !stuck_recovery::source_sample_is_current(
          array_stamp, sample_stamp, cfg.timeout_sec) ||
        !stuck_recovery::source_timestamp_is_monotonic(
          sample_stamp,
          tracked.has_sample ? std::optional<double>{tracked.stamp_sec} : std::nullopt);
      if (source_sample_invalid) {
        last_message_has_invalid_sample_ = true;
      }
      double vx = 0.0;
      double vy = 0.0;
      double ax = 0.0;
      double ay = 0.0;
      double velocity_observation_interval_sec = 0.0;
      bool position_jump = false;
      bool invalid_velocity = false;
      bool velocity_observation_valid = false;
      bool motion_estimate_valid = false;
      if (tracked.has_sample) {
        const double dt = sample_stamp - tracked.stamp_sec;
        const double dx = vehicle.position.x - tracked.x;
        const double dy = vehicle.position.y - tracked.y;
        const double jump = std::hypot(dx, dy);
        const auto sample_continuity =
          overtake_core::classify_opponent_sample_continuity(
          overtake_core::OpponentSampleContinuityRequest{
            tracked.has_sample,
            tracked.motion_estimate_valid,
            tracked.stamp_sec,
            sample_stamp,
            tracked.x,
            tracked.y,
            vehicle.position.x,
            vehicle.position.y});
        // AWSIM V2X can update near 1 Hz, so a normally moving kart may travel
        // more than the fixed spatial jump threshold between samples. Scale
        // the admissible displacement by dt and the configured safety speed;
        // the fixed threshold remains the minimum tolerance for short-dt
        // localization noise and discontinuities.
        const double admissible_jump = dt > kEps ?
          std::max(cfg.position_jump_threshold, cfg.v_max_safety * dt) :
          cfg.position_jump_threshold;
        position_jump = !std::isfinite(dt) || dt < -kEps || jump > admissible_jump;
        if (position_jump) {
          last_message_has_invalid_sample_ = true;
        }
        if (
          sample_continuity ==
          overtake_core::OpponentSampleContinuity::ReusableDuplicate)
        {
          // The bridge can repeat an identical source sample while advancing
          // the array receipt time. Preserve the last motion proof; replacing
          // it with an uninitialised estimate makes the otherwise current
          // dynamic world disappear for one control cycle.
          vx = tracked.vx;
          vy = tracked.vy;
          ax = tracked.ax;
          ay = tracked.ay;
          velocity_observation_interval_sec =
            tracked.velocity_observation_interval_sec;
          velocity_observation_valid = true;
          motion_estimate_valid = true;
        } else if (
          sample_continuity ==
          overtake_core::OpponentSampleContinuity::InvalidNonadvancing)
        {
          invalid_velocity = true;
          last_message_has_invalid_sample_ = true;
        } else if (dt > kEps && !position_jump) {
          const double observed_vx = dx / dt;
          const double observed_vy = dy / dt;
          if (std::hypot(observed_vx, observed_vy) > cfg.v_max_safety) {
            invalid_velocity = true;
            last_message_has_invalid_sample_ = true;
            vx = 0.0;
            vy = 0.0;
          } else {
            const auto filtered_motion =
              overtake_core::update_opponent_motion_filter(
              overtake_core::OpponentMotionFilterRequest{
                tracked.motion_estimate_valid,
                tracked.vx,
                tracked.vy,
                tracked.ax,
                tracked.ay,
                observed_vx,
                observed_vy,
                dt,
                cfg.prediction_velocity_filter_gain,
                cfg.prediction_acceleration_filter_gain,
                cfg.prediction_maximum_acceleration});
            if (filtered_motion.valid) {
              vx = filtered_motion.velocity_x_mps;
              vy = filtered_motion.velocity_y_mps;
              ax = filtered_motion.acceleration_x_mps2;
              ay = filtered_motion.acceleration_y_mps2;
              motion_estimate_valid = true;
              velocity_observation_valid = true;
              velocity_observation_interval_sec = dt;
            } else {
              invalid_velocity = true;
              last_message_has_invalid_sample_ = true;
            }
          }
        }
      }

      tracked.id = id;
      tracked.x = vehicle.position.x;
      tracked.y = vehicle.position.y;
      tracked.covariance_x = std::max(0.0, static_cast<double>(vehicle.covariance.x));
      tracked.covariance_y = std::max(0.0, static_cast<double>(vehicle.covariance.y));
      tracked.stamp_sec = sample_stamp;
      tracked.receipt_sec = receipt_sec;
      tracked.vx = vx;
      tracked.vy = vy;
      tracked.ax = ax;
      tracked.ay = ay;
      tracked.velocity_observation_interval_sec = velocity_observation_interval_sec;
      tracked.observation_generation = observation_generation_;
      tracked.recovery_epoch = recovery_epoch_;
      tracked.recovery_sample_valid =
        !array_header_invalid && !empty_id && !duplicate_id && !invalid_geometry &&
        !source_sample_invalid && !position_jump && !invalid_velocity;
      tracked.has_sample = true;
      tracked.position_jump = position_jump;
      tracked.invalid_velocity = invalid_velocity;
      tracked.velocity_observation_valid =
        velocity_observation_valid && !array_header_invalid && !empty_id &&
        !duplicate_id && !invalid_geometry && !source_sample_invalid;
      tracked.motion_estimate_valid =
        motion_estimate_valid && tracked.velocity_observation_valid;
    }
    last_message_vehicle_ids_.assign(message_ids.begin(), message_ids.end());
    if (
      !last_message_has_empty_id_ && !last_message_has_duplicate_id_ &&
      !last_message_has_invalid_sample_)
    {
      peer_identity_tracker_.observe_valid_message(last_message_vehicle_ids_);
    }
    last_message_recovery_epoch_ = recovery_epoch_;
  }

  std::vector<TrackedVehicle> active_vehicles(const double now_sec)
  {
    std::vector<TrackedVehicle> vehicles;
    std::lock_guard<std::mutex> lock(mutex_);
    for (const auto & kv : vehicles_) {
      const auto & tracked = kv.second;
      if (!tracked.has_sample) {
        continue;
      }
      const double age_sec = now_sec - tracked.receipt_sec;
      if (!overtake_core::is_v2x_receipt_age_fresh(
          age_sec, cfg.timeout_sec, kV2XReceiptFutureToleranceSec))
      {
        continue;
      }
      vehicles.push_back(tracked);
    }
    return vehicles;
  }

  Diagnostics diagnostics(const double now_sec)
  {
    Diagnostics output;
    std::lock_guard<std::mutex> lock(mutex_);
    if (!last_message_receipt_sec_.has_value()) {
      return output;
    }
    output.receipt_age_sec = now_sec - last_message_receipt_sec_.value();
    output.source_age_sec = last_message_source_stamp_sec_.has_value() ?
      now_sec - last_message_source_stamp_sec_.value() :
      std::numeric_limits<double>::infinity();
    output.receipt_interval_sec = last_message_receipt_interval_sec_.value_or(
      std::numeric_limits<double>::infinity());
    output.message_vehicle_count = last_message_vehicle_count_;
    output.message_invalid =
      last_message_has_empty_id_ || last_message_has_duplicate_id_ ||
      last_message_has_invalid_sample_;
    for (const auto & item : vehicles_) {
      const auto & tracked = item.second;
      const double age_sec = now_sec - tracked.receipt_sec;
      if (
        tracked.has_sample &&
        overtake_core::is_v2x_receipt_age_fresh(
          age_sec, cfg.timeout_sec, kV2XReceiptFutureToleranceSec))
      {
        ++output.fresh_vehicle_count;
        output.position_jump_count += tracked.position_jump ? 1U : 0U;
        output.invalid_velocity_count += tracked.invalid_velocity ? 1U : 0U;
      }
    }
    if (
      !std::isfinite(output.receipt_age_sec) ||
      output.receipt_age_sec < -kV2XReceiptFutureToleranceSec)
    {
      output.health = "Invalid";
    } else if (output.receipt_age_sec > cfg.timeout_sec) {
      output.health = "Stale";
    } else if (
      !std::isfinite(output.source_age_sec) ||
      output.source_age_sec < -kV2XSourceFutureToleranceSec ||
      output.message_invalid)
    {
      output.health = "Invalid";
    } else if (
      output.source_age_sec > cfg.timeout_sec ||
      output.position_jump_count > 0U || output.invalid_velocity_count > 0U)
    {
      output.health = "Degraded";
    } else {
      output.health = "Healthy";
    }
    return output;
  }

  EmptyWorldObservation empty_world_observation(const double now_sec)
  {
    EmptyWorldObservation output;
    std::lock_guard<std::mutex> lock(mutex_);
    output.observation_generation = observation_generation_;
    output.receipt_sec = last_message_receipt_sec_.value_or(
      std::numeric_limits<double>::quiet_NaN());
    for (const auto & item : vehicles_) {
      const auto & tracked = item.second;
      if (!tracked.has_sample) {
        continue;
      }
      const double age_sec = now_sec - tracked.receipt_sec;
      if (overtake_core::is_v2x_receipt_age_fresh(
          age_sec, cfg.timeout_sec, kV2XReceiptFutureToleranceSec))
      {
        ++output.active_vehicle_count;
      }
    }
    if (!last_message_receipt_sec_.has_value() ||
      !last_message_source_stamp_sec_.has_value())
    {
      return output;
    }
    const double receipt_age_sec = now_sec - last_message_receipt_sec_.value();
    const double source_age_sec = now_sec - last_message_source_stamp_sec_.value();
    output.current = observation_generation_ != 0U &&
      last_message_vehicle_count_ == 0U &&
      output.active_vehicle_count == 0U &&
      overtake_core::is_v2x_receipt_age_fresh(
      receipt_age_sec, cfg.timeout_sec, kV2XReceiptFutureToleranceSec) &&
      source_age_sec >= -kV2XSourceFutureToleranceSec &&
      source_age_sec <= cfg.timeout_sec &&
      !last_message_has_empty_id_ && !last_message_has_duplicate_id_ &&
      !last_message_has_invalid_sample_;
    return output;
  }

  DynamicWorldObservation dynamic_world_observation(const double now_sec)
  {
    DynamicWorldObservation output;
    std::lock_guard<std::mutex> lock(mutex_);
    output.observation_generation = observation_generation_;
    output.receipt_sec = last_message_receipt_sec_.value_or(
      std::numeric_limits<double>::quiet_NaN());
    output.source_sec = last_message_source_stamp_sec_.value_or(
      std::numeric_limits<double>::quiet_NaN());
    if (
      observation_generation_ == 0U ||
      !last_message_receipt_sec_.has_value() ||
      !last_message_source_stamp_sec_.has_value() ||
      last_message_has_empty_id_ || last_message_has_duplicate_id_ ||
      last_message_has_invalid_sample_ ||
      last_message_vehicle_ids_.size() != last_message_vehicle_count_)
    {
      return output;
    }
    const double receipt_age_sec = now_sec - output.receipt_sec;
    const double source_age_sec = now_sec - output.source_sec;
    if (
      !overtake_core::is_v2x_receipt_age_fresh(
        receipt_age_sec, cfg.timeout_sec, kV2XReceiptFutureToleranceSec) ||
      !std::isfinite(source_age_sec) ||
      source_age_sec < -kV2XSourceFutureToleranceSec ||
      source_age_sec > cfg.timeout_sec)
    {
      return output;
    }
    output.vehicles.reserve(last_message_vehicle_ids_.size());
    for (const auto & id : last_message_vehicle_ids_) {
      const auto found = vehicles_.find(id);
      if (found == vehicles_.end()) {
        output.vehicles.clear();
        return output;
      }
      auto vehicle = found->second;
      if (
        !vehicle.has_sample ||
        vehicle.observation_generation != observation_generation_ ||
        vehicle.receipt_sec != output.receipt_sec || vehicle.position_jump ||
        vehicle.invalid_velocity || !vehicle.velocity_observation_valid ||
        !vehicle.motion_estimate_valid || vehicle.id.empty() ||
        !std::isfinite(vehicle.x) || !std::isfinite(vehicle.y) ||
        !std::isfinite(vehicle.vx) || !std::isfinite(vehicle.vy) ||
        !std::isfinite(vehicle.stamp_sec) ||
        !std::isfinite(vehicle.covariance_x) ||
        !std::isfinite(vehicle.covariance_y) ||
        vehicle.covariance_x < 0.0 || vehicle.covariance_y < 0.0)
      {
        output.vehicles.clear();
        return output;
      }
      const double sample_age_sec = now_sec - vehicle.stamp_sec;
      if (
        !std::isfinite(sample_age_sec) ||
        sample_age_sec < -kV2XSourceFutureToleranceSec ||
        sample_age_sec > cfg.timeout_sec)
      {
        output.vehicles.clear();
        return output;
      }
      const double nonnegative_age_sec = std::max(0.0, sample_age_sec);
      vehicle.x += vehicle.vx * nonnegative_age_sec;
      vehicle.y += vehicle.vy * nonnegative_age_sec;
      vehicle.stamp_sec = now_sec;
      output.vehicles.push_back(std::move(vehicle));
    }
    output.current = true;
    return output;
  }

  bool has_complete_message(const double now_sec)
  {
    std::lock_guard<std::mutex> lock(mutex_);
    if (
      !track_recovery_completeness_ || !last_message_receipt_sec_.has_value() ||
      !last_message_recovery_epoch_.has_value() ||
      last_message_recovery_epoch_.value() != recovery_epoch_)
    {
      return false;
    }
    const double age_sec = now_sec - last_message_receipt_sec_.value();
    return overtake_core::is_v2x_receipt_age_fresh(
      age_sec, cfg.timeout_sec, kV2XReceiptFutureToleranceSec) &&
           !last_message_has_empty_id_ && !last_message_has_duplicate_id_ &&
           !last_message_has_invalid_sample_ &&
           peer_identity_tracker_.is_complete(last_message_vehicle_ids_);
  }

  bool has_complete_tracked_set(const double now_sec)
  {
    std::lock_guard<std::mutex> lock(mutex_);
    if (
      !track_recovery_completeness_ || !last_message_receipt_sec_.has_value() ||
      !last_message_recovery_epoch_.has_value() ||
      last_message_recovery_epoch_.value() != recovery_epoch_)
    {
      return false;
    }
    std::vector<std::string> fresh_vehicle_ids;
    for (const auto & item : vehicles_) {
      const auto & tracked = item.second;
      if (tracked.recovery_epoch != recovery_epoch_) {
        continue;
      }
      const double age_sec = now_sec - tracked.receipt_sec;
      if (
        !tracked.has_sample ||
        !overtake_core::is_v2x_receipt_age_fresh(
          age_sec, cfg.timeout_sec, kV2XReceiptFutureToleranceSec))
      {
        continue;
      }
      if (
        tracked.id.empty() || !tracked.recovery_sample_valid ||
        tracked.position_jump || tracked.invalid_velocity ||
        !std::isfinite(tracked.x) || !std::isfinite(tracked.y) ||
        !std::isfinite(tracked.vx) || !std::isfinite(tracked.vy))
      {
        return false;
      }
      fresh_vehicle_ids.push_back(tracked.id);
    }
    return peer_identity_tracker_.is_complete(fresh_vehicle_ids);
  }

  void begin_recovery_tracking_epoch()
  {
    std::lock_guard<std::mutex> lock(mutex_);
    ++recovery_epoch_;
  }

  void reset_all_tracking()
  {
    std::lock_guard<std::mutex> lock(mutex_);
    ++recovery_epoch_;
    vehicles_.clear();
    last_message_receipt_sec_.reset();
    last_message_receipt_interval_sec_.reset();
    last_message_source_stamp_sec_.reset();
    last_message_recovery_epoch_.reset();
    last_message_vehicle_count_ = 0U;
    last_message_vehicle_ids_.clear();
    peer_identity_tracker_.reset();
    last_message_has_empty_id_ = false;
    last_message_has_duplicate_id_ = false;
    last_message_has_invalid_sample_ = false;
  }

  void reset_low_speed_target_lock()
  {
    std::lock_guard<std::mutex> lock(mutex_);
    low_speed_locked_target_ey_.reset();
    low_speed_locked_side_sign_.reset();
  }

  void lock_low_speed_pass_side(const int pass_side_sign)
  {
    if (pass_side_sign == 0) {
      return;
    }
    std::lock_guard<std::mutex> lock(mutex_);
    low_speed_locked_side_sign_ = pass_side_sign;
  }

  void reset_low_speed_targets()
  {
    std::lock_guard<std::mutex> lock(mutex_);
    low_speed_locked_target_ey_.reset();
    low_speed_locked_side_sign_.reset();
    last_target_ey_.reset();
    last_logged_local_path_corridor_enforced_.reset();
  }

  /// Commit only the continuity hint of an already evaluated speculative
  /// branch. Candidate generation runs on a tactical snapshot, so rejecting
  /// that branch cannot overwrite the live planner state.
  void commit_selected_gap_plan(const GapPlannerOutput & output)
  {
    if (!output.active || !output.feasible) {
      return;
    }
    const std::size_t sample_count = std::min(
      output.target_active.size(), output.target_ey.size());
    for (std::size_t i = 0; i < sample_count; ++i) {
      if (!output.target_active[i] || !std::isfinite(output.target_ey[i])) {
        continue;
      }
      std::lock_guard<std::mutex> lock(mutex_);
      last_target_ey_ = output.target_ey[i];
      return;
    }
  }

  GapPlannerOutput plan_stopped_vehicle_local_path(
    const BicycleModel & model, const int ref_wp_id, const int N, const Eigen::VectorXd & base_lb,
    const Eigen::VectorXd & base_ub, const double now_sec, const V2XBehaviorConfig & behavior_cfg,
    const bool update_last_target = true, const int forced_pass_side_sign = 0)
  {
    GapPlannerOutput output;
    if (!cfg.enabled || !behavior_cfg.low_speed_local_path_enabled || N <= 0) {
      return output;
    }

    output.lb.assign(N, 0.0);
    output.ub.assign(N, 0.0);
    output.target_ey.assign(N, 0.0);
    output.target_active.assign(N, false);
    for (int i = 0; i < N; ++i) {
      output.lb[i] = base_lb[i];
      output.ub[i] = base_ub[i];
      output.target_ey[i] = 0.0;
    }

    struct ProjectedVehicle
    {
      TrackedVehicle vehicle;
      int wp_id{};
      double s{};
      double lateral{};
      double covariance_margin{};
      bool stopped_mission_trigger{false};
    };

    const auto vehicles = active_vehicles(now_sec);
    if (vehicles.empty()) {
      return output;
    }

    const int configured_pass_side = low_speed_pass_side_sign();
    int locked_pass_side = 0;
    {
      std::lock_guard<std::mutex> lock(mutex_);
      locked_pass_side = low_speed_locked_side_sign_.value_or(0);
    }

    const double lookahead_distance =
      std::max(behavior_cfg.low_speed_avoidance_distance, behavior_cfg.low_speed_avoidance_lookahead_distance);
    const double scan_resolution = std::max(0.2, model.reference_path->resolution);
    const int scan_steps =
      std::max(N + 1, static_cast<int>(std::ceil(lookahead_distance / scan_resolution)) + 4);
    std::vector<ProjectedVehicle> projected;
    for (const auto & vehicle : vehicles) {
      const double self_distance =
        std::hypot(vehicle.x - model.temporal_state.x, vehicle.y - model.temporal_state.y);
      if (self_distance < cfg.self_filter_radius) {
        continue;
      }
      const double vehicle_speed = std::hypot(vehicle.vx, vehicle.vy);

      double best_distance = std::numeric_limits<double>::infinity();
      int best_wp_id = ref_wp_id;
      for (int offset = 0; offset <= scan_steps; ++offset) {
        const int candidate_wp_id = ref_wp_id + offset;
        const auto & waypoint = model.reference_path->get_waypoint(candidate_wp_id);
        const double distance = std::hypot(vehicle.x - waypoint.x, vehicle.y - waypoint.y);
        if (distance < best_distance) {
          best_distance = distance;
          best_wp_id = candidate_wp_id;
        }
      }

      const auto & waypoint = model.reference_path->get_waypoint(best_wp_id);
      const double dx = vehicle.x - waypoint.x;
      const double dy = vehicle.y - waypoint.y;
      const double along_wp = std::cos(waypoint.psi) * dx + std::sin(waypoint.psi) * dy;
      const double s = forward_path_distance(*model.reference_path, ref_wp_id, best_wp_id) + along_wp;
      if (s <= 0.0 || s > lookahead_distance) {
        continue;
      }

      ProjectedVehicle projected_vehicle;
      projected_vehicle.vehicle = vehicle;
      projected_vehicle.wp_id = best_wp_id;
      projected_vehicle.s = s;
      projected_vehicle.lateral = -std::sin(waypoint.psi) * dx + std::cos(waypoint.psi) * dy;
      projected_vehicle.covariance_margin = std::max(vehicle.covariance_x, vehicle.covariance_y);
      // A stopped vehicle triggers this maneuver, but every active vehicle in
      // the same lookahead is a physical blocker. Filtering moving vehicles
      // here validated corridors that were already occupied by the next kart.
      projected_vehicle.stopped_mission_trigger =
        vehicle_speed <= behavior_cfg.low_speed_avoidance_max_front_speed;
      projected.push_back(projected_vehicle);
    }

    if (projected.empty()) {
      return output;
    }

    std::sort(
      projected.begin(), projected.end(),
      [](const ProjectedVehicle & lhs, const ProjectedVehicle & rhs) { return lhs.s < rhs.s; });
    const bool stopped_trigger_in_range = std::any_of(
      projected.begin(), projected.end(),
      [&](const ProjectedVehicle & vehicle) {
        return vehicle.stopped_mission_trigger &&
               vehicle.s <= behavior_cfg.low_speed_avoidance_distance;
      });
    // Once a side has been locked, keep evaluating the whole vehicle pack even
    // if the original stopped target starts moving. Before commitment, a
    // stopped target inside the trigger distance is still mandatory.
    if (!stopped_trigger_in_range && locked_pass_side == 0) {
      return output;
    }

    struct SideCandidate
    {
      bool feasible{true};
      LateralInterval intersection{
        -std::numeric_limits<double>::infinity(), std::numeric_limits<double>::infinity()};
      double min_width{std::numeric_limits<double>::infinity()};
    };

    // Low-speed stopped-vehicle bypass has its own clearance threshold. Using
    // the general racing gap minimum here made the dedicated parameter unable
    // to relax narrow car-to-wall gaps in Gate2-like layouts.
    const double required_width =
      std::max(0.0, behavior_cfg.low_speed_avoidance_min_gap_width);
    const auto evaluate_side = [&](const int pass_side_sign) {
      SideCandidate candidate;
      for (const auto & vehicle : projected) {
        const auto & waypoint = model.reference_path->get_waypoint(vehicle.wp_id);
        LateralInterval base{waypoint.lb_sm, waypoint.ub_sm};
        if (base.width() <= kEps) {
          base = {waypoint.lb, waypoint.ub};
        }
        const double wall_margin =
          std::min(std::max(0.0, cfg.wall_clearance_margin), std::max(0.0, base.width()) * 0.45);
        const double inflated_radius =
          std::max(0.0, cfg.vehicle_radius + cfg.prediction_margin + vehicle.covariance_margin);
        const double obstacle_lower = vehicle.lateral - inflated_radius;
        const double obstacle_upper = vehicle.lateral + inflated_radius;
        const LateralInterval interval = pass_side_sign < 0 ?
          LateralInterval{base.lower + wall_margin, obstacle_lower} :
          LateralInterval{obstacle_upper, base.upper - wall_margin};
        candidate.min_width = std::min(candidate.min_width, interval.width());
        candidate.intersection.lower = std::max(candidate.intersection.lower, interval.lower);
        candidate.intersection.upper = std::min(candidate.intersection.upper, interval.upper);
        if (
          interval.width() < required_width ||
          candidate.intersection.width() < required_width) {
          candidate.feasible = false;
        }
      }
      return candidate;
    };

    const auto side_target_ey = [&](const SideCandidate & candidate, const int side_sign) {
      const double interval_width = candidate.intersection.width();
      const double vehicle_margin =
        std::min(std::max(0.0, cfg.vehicle_side_target_margin), interval_width * 0.5);
      const double center_target = candidate.intersection.center();
      const double vehicle_side_target = side_sign < 0 ?
        candidate.intersection.upper - vehicle_margin :
        candidate.intersection.lower + vehicle_margin;
      return center_target + cfg.wall_avoidance_bias * (vehicle_side_target - center_target);
    };

    const auto right = evaluate_side(-1);
    const auto left = evaluate_side(1);
    int pass_side_sign = forced_pass_side_sign != 0 ?
      forced_pass_side_sign :
      (configured_pass_side != 0 ? configured_pass_side : locked_pass_side);
    SideCandidate selected_side;
    if (pass_side_sign != 0) {
      selected_side = pass_side_sign < 0 ? right : left;
    } else {
      if (right.feasible && left.feasible) {
        const auto side = v2x_overtake_core::select_reachable_low_speed_pass_side(
          v2x_overtake_core::LowSpeedPassSideRequest{
            model.spatial_state.e_y,
            {true, side_target_ey(left, 1), left.min_width},
            {true, side_target_ey(right, -1), right.min_width}});
        pass_side_sign = static_cast<int>(side);
        selected_side = pass_side_sign < 0 ? right : left;
      } else if (right.feasible) {
        pass_side_sign = -1;
        selected_side = right;
      } else if (left.feasible) {
        pass_side_sign = 1;
        selected_side = left;
      } else {
        selected_side.feasible = false;
      }
    }

    output.active = true;
    output.feasible = selected_side.feasible && pass_side_sign != 0;
    output.pass_side_sign = pass_side_sign;
    if (!output.feasible) {
      output.target_velocity_limit = std::max(0.0, cfg.no_gap_target_velocity);
      if (update_last_target) {
        reset_low_speed_targets();
      }
      return output;
    }

    const double interval_width = selected_side.intersection.width();
    const double vehicle_margin =
      std::min(std::max(0.0, cfg.vehicle_side_target_margin), interval_width * 0.5);
    const double center_target_ey = selected_side.intersection.center();
    const double vehicle_side_target_ey = pass_side_sign < 0 ?
      selected_side.intersection.upper - vehicle_margin :
      selected_side.intersection.lower + vehicle_margin;
    const double pass_target_ey =
      center_target_ey +
      cfg.wall_avoidance_bias * (vehicle_side_target_ey - center_target_ey);
    const double pass_begin_s =
      std::max(0.5, projected.front().s - 0.5 * std::max(0.0, cfg.vehicle_length));
    const double pass_end_s =
      projected.back().s + 0.5 * std::max(0.0, cfg.vehicle_length) +
      std::max(0.0, behavior_cfg.low_speed_local_path_pass_clearance);
    const double approach_distance =
      std::max(0.5, pass_begin_s * std::max(0.1, cfg.low_speed_pass_ramp_ratio));
    const bool enforce_pass_corridor =
      v2x_overtake_core::has_entered_low_speed_pass_corridor(
        model.spatial_state.e_y, selected_side.intersection.lower,
        selected_side.intersection.upper);
    output.pass_corridor_enforced = enforce_pass_corridor;
    output.pass_target_ey = pass_target_ey;
    for (int i = 0; i < N; ++i) {
      const double point_s = forward_path_distance(*model.reference_path, ref_wp_id, ref_wp_id + i + 1);
      const LateralInterval base_interval{base_lb[i], base_ub[i]};
      LateralInterval local_corridor = selected_side.intersection;
      if (!enforce_pass_corridor || point_s < approach_distance) {
        local_corridor.lower = std::min(model.spatial_state.e_y, selected_side.intersection.lower);
        local_corridor.upper = std::max(model.spatial_state.e_y, selected_side.intersection.upper);
      }
      output.lb[i] = std::max(base_interval.lower, local_corridor.lower);
      output.ub[i] = std::min(base_interval.upper, local_corridor.upper);
      if (output.ub[i] < output.lb[i]) {
        output.feasible = false;
        output.target_velocity_limit = std::max(0.0, cfg.no_gap_target_velocity);
        if (update_last_target) {
          reset_low_speed_targets();
        }
        return output;
      }

      double target_ey = pass_target_ey;
      if (point_s <= approach_distance) {
        const double progress = smoothstep(point_s / approach_distance);
        target_ey = model.spatial_state.e_y + progress * (pass_target_ey - model.spatial_state.e_y);
      }
      output.target_ey[i] = clip(target_ey, output.lb[i], output.ub[i]);
      output.target_active[i] = true;
    }
    output.target_velocity_limit =
      v2x_overtake_core::resolve_low_speed_pass_velocity(
        std::max(0.0, behavior_cfg.low_speed_avoidance_velocity),
        std::max(0.0, behavior_cfg.low_speed_avoidance_shift_velocity),
        enforce_pass_corridor);

    if (update_last_target) {
      if (
        last_logged_local_path_side_ != pass_side_sign ||
        std::abs(last_logged_local_path_target_ey_ - pass_target_ey) > 0.1 ||
        last_logged_local_path_corridor_enforced_ != enforce_pass_corridor) {
        RCLCPP_INFO(
          rclcpp::get_logger("mpc_controller"),
          "V2X local path selected: side=%s, target_ey=%.2f, center_ey=%.2f, "
          "vehicle_side_ey=%.2f, width=%.2f, approach_s=%.2f, pass_s=[%.2f, %.2f], "
          "vehicles=%zu, corridor=%s, required_width=%.2f, "
          "right=%s/min=%.2f/range=[%.2f,%.2f], left=%s/min=%.2f/range=[%.2f,%.2f]",
          pass_side_sign < 0 ? "right" : "left", pass_target_ey,
          center_target_ey, vehicle_side_target_ey, interval_width, approach_distance, pass_begin_s,
          pass_end_s, projected.size(), enforce_pass_corridor ? "hard" : "shift_target",
          required_width, right.feasible ? "ok" : "blocked", right.min_width,
          right.intersection.lower, right.intersection.upper,
          left.feasible ? "ok" : "blocked", left.min_width,
          left.intersection.lower, left.intersection.upper);
        last_logged_local_path_side_ = pass_side_sign;
        last_logged_local_path_target_ey_ = pass_target_ey;
        last_logged_local_path_corridor_enforced_ = enforce_pass_corridor;
      }
      std::lock_guard<std::mutex> lock(mutex_);
      low_speed_locked_side_sign_ = pass_side_sign;
      last_target_ey_ = output.target_ey.empty() ? pass_target_ey : output.target_ey.back();
    }
    return output;
  }

  GapPlannerOutput plan(
    const BicycleModel & model, const int ref_wp_id, const int N, const Eigen::VectorXd & base_lb,
    const Eigen::VectorXd & base_ub, const double now_sec, const bool update_last_target = true,
    const bool allow_vehicle_vehicle_gap = false,
    const double max_self_distance = std::numeric_limits<double>::infinity(),
    const int forced_pass_side_sign = 0,
    const std::optional<double> min_gap_width_override = std::nullopt,
    const bool prefer_short_lateral_path = false,
    const std::optional<std::pair<std::string, std::string>> &
    locked_vehicle_vehicle_gap = std::nullopt,
    const std::optional<double> locked_corridor_target_ey = std::nullopt,
    const double start_grid_inter_vehicle_longitudinal_span = 0.0,
    const double start_grid_inter_vehicle_lookbehind_distance = 0.0,
    const double start_grid_inter_vehicle_lateral_radius = 0.0,
    const std::optional<double> prediction_ego_speed_override_mps = std::nullopt,
    const double forced_pass_side_transition_distance_m = 0.0,
    const double forced_pass_side_transition_min_shift_m = 0.0)
  {
    GapPlannerOutput output;
    if (!cfg.enabled || N <= 0) {
      return output;
    }

    std::vector<TrackedVehicle> vehicles;
    const bool use_corridor_center_desired = allow_vehicle_vehicle_gap &&
                                            !prefer_short_lateral_path &&
                                            base_lb.size() > 0 && base_ub.size() > 0;
    double desired_ey = use_corridor_center_desired ?
      0.5 * (base_lb[0] + base_ub[0]) :
      model.spatial_state.e_y;
    if (locked_corridor_target_ey.has_value()) {
      desired_ey = locked_corridor_target_ey.value();
    }
    // Gate2-like stopped vehicle rows need the target to be recomputed after each passed vehicle.
    // Keep last_target_ey_ only as a continuity hint; do not pin one absolute lateral target.
    const bool use_low_speed_target_lock = false;
    std::optional<double> low_speed_locked_target_ey;
    const int configured_low_speed_pass_side = low_speed_pass_side_sign();
    int low_speed_pass_side = 0;
    {
      std::lock_guard<std::mutex> lock(mutex_);
      if (use_low_speed_target_lock && low_speed_locked_target_ey_.has_value()) {
        low_speed_locked_target_ey = low_speed_locked_target_ey_;
        desired_ey = low_speed_locked_target_ey.value();
      } else if (!use_corridor_center_desired && last_target_ey_.has_value()) {
        desired_ey = last_target_ey_.value();
      }
      if (forced_pass_side_sign != 0) {
        low_speed_pass_side = forced_pass_side_sign;
      } else if (allow_vehicle_vehicle_gap) {
        low_speed_pass_side = configured_low_speed_pass_side != 0 ?
          configured_low_speed_pass_side :
          low_speed_locked_side_sign_.value_or(0);
      }
      for (const auto & kv : vehicles_) {
        const auto & tracked = kv.second;
        if (!tracked.has_sample) {
          continue;
        }
        if (!overtake_core::is_v2x_receipt_age_fresh(
            now_sec - tracked.receipt_sec, cfg.timeout_sec,
            kV2XReceiptFutureToleranceSec))
        {
          continue;
        }
        vehicles.push_back(tracked);
      }
    }

    const bool forced_side_transition_requested =
      forced_pass_side_sign != 0 &&
      std::isfinite(forced_pass_side_transition_distance_m) &&
      forced_pass_side_transition_distance_m > kEps;
    output.forced_side_transition_requested = forced_side_transition_requested;
    output.forced_side_transition_required_connected_distance_m =
      forced_side_transition_requested ? forced_pass_side_transition_distance_m : 0.0;
    output.forced_side_transition_reason =
      forced_side_transition_requested ? "awaiting-connected-gateway" : "not-requested";

    if (std::isfinite(max_self_distance)) {
      vehicles.erase(
        std::remove_if(
          vehicles.begin(), vehicles.end(),
          [&](const TrackedVehicle & vehicle) {
            return std::hypot(vehicle.x - model.temporal_state.x, vehicle.y - model.temporal_state.y) >
                   max_self_distance;
          }),
        vehicles.end());
    }

    if (vehicles.empty()) {
      return output;
    }

    std::unordered_map<std::string, v2x_overtake_core::ForwardCourseProjection>
    course_aligned_projections;
    struct CourseLateralObservation
    {
      double current_lateral{};
      double previous_lateral{};
      double sample_interval_sec{};
    };
    std::unordered_map<std::string, CourseLateralObservation>
    course_lateral_observations;
    if (
      (cfg.prediction_use_course_progress ||
      cfg.prediction_use_course_lateral_velocity) &&
      model.reference_path->n_waypoints >= 2)
    {
      std::vector<v2x_overtake_core::CoursePoint> course_path;
      course_path.reserve(static_cast<std::size_t>(model.reference_path->n_waypoints));
      for (int waypoint_id = 0; waypoint_id < model.reference_path->n_waypoints; ++waypoint_id) {
        const auto & waypoint = model.reference_path->get_waypoint(waypoint_id);
        course_path.push_back({waypoint.x, waypoint.y});
      }

      double horizon_course_span = 0.0;
      for (int i = 1; i < N; ++i) {
        horizon_course_span +=
          model.reference_path->get_waypoint(ref_wp_id + i).distance_to(
          model.reference_path->get_waypoint(ref_wp_id + i - 1));
      }
      double maximum_corridor_offset = 0.0;
      for (Eigen::Index i = 0; i < base_lb.size(); ++i) {
        if (std::isfinite(base_lb[i])) {
          maximum_corridor_offset =
            std::max(maximum_corridor_offset, std::abs(base_lb[i]));
        }
        if (std::isfinite(base_ub[i])) {
          maximum_corridor_offset =
            std::max(maximum_corridor_offset, std::abs(base_ub[i]));
        }
      }
      const double projection_lookbehind = std::max(
        3.0, 0.5 * (std::max(0.0, model.length) + std::max(0.0, cfg.vehicle_length)));
      const double projection_max_cross_track = std::max(
        3.0,
        maximum_corridor_offset + std::max(0.0, cfg.vehicle_radius) +
        std::max(0.0, cfg.prediction_margin) + 0.5 * std::max(0.0, model.width));

      for (const auto & vehicle : vehicles) {
        const double age = std::max(0.0, now_sec - vehicle.stamp_sec);
        const double current_x = vehicle.x + vehicle.vx * age;
        const double current_y = vehicle.y + vehicle.vy * age;
        const double target_speed = std::hypot(vehicle.vx, vehicle.vy);
        const double projection_lookahead = std::max(
          5.0,
          horizon_course_span + target_speed * std::max(0.0, cfg.prediction_time) +
          std::max(0.0, model.length) + std::max(0.0, cfg.vehicle_length));
        v2x_overtake_core::ForwardCourseProjectionRequest projection_request;
        projection_request.start_index =
          static_cast<std::size_t>(std::max(0, ref_wp_id));
        projection_request.circular = model.reference_path->circular;
        projection_request.origin_x_m = model.temporal_state.x;
        projection_request.origin_y_m = model.temporal_state.y;
        projection_request.target_x_m = current_x;
        projection_request.target_y_m = current_y;
        projection_request.target_vx_mps = vehicle.vx;
        projection_request.target_vy_mps = vehicle.vy;
        projection_request.lookbehind_distance_m = projection_lookbehind;
        projection_request.lookahead_distance_m = projection_lookahead;
        projection_request.max_cross_track_distance_m = projection_max_cross_track;
        try {
          if (cfg.prediction_use_course_progress) {
            const auto projection =
              v2x_overtake_core::project_forward_course_progress(course_path, projection_request);
            if (projection.valid) {
              course_aligned_projections.emplace(vehicle.id, projection);
            }
          }
          if (
            cfg.prediction_use_course_lateral_velocity &&
            vehicle.velocity_observation_valid &&
            vehicle.velocity_observation_interval_sec > kEps)
          {
            auto current_request = projection_request;
            current_request.target_x_m = vehicle.x;
            current_request.target_y_m = vehicle.y;
            const auto current_projection =
              v2x_overtake_core::project_forward_course_progress(
              course_path, current_request);
            if (current_projection.valid) {
              auto previous_request = current_request;
              previous_request.target_x_m =
                vehicle.x - vehicle.vx * vehicle.velocity_observation_interval_sec;
              previous_request.target_y_m =
                vehicle.y - vehicle.vy * vehicle.velocity_observation_interval_sec;
              previous_request.lookbehind_distance_m +=
                target_speed * vehicle.velocity_observation_interval_sec;
              previous_request.preferred_target_path_progress_m =
                current_projection.target_path_progress_m;
              previous_request.max_target_path_progress_change_m = std::max(
                1.0,
                target_speed * vehicle.velocity_observation_interval_sec + 1.0);
              const auto previous_projection =
                v2x_overtake_core::project_forward_course_progress(
                course_path, previous_request);
              if (previous_projection.valid) {
                const CourseLateralObservation observation{
                  current_projection.lateral_m,
                  previous_projection.lateral_m,
                  vehicle.velocity_observation_interval_sec};
                course_lateral_observations.emplace(
                  vehicle.id, observation);
                const auto diagnostic =
                  v2x_overtake_core::resolve_course_lateral_prediction(
                  v2x_overtake_core::CourseLateralPredictionRequest{
                    true, true, true,
                    observation.current_lateral, observation.previous_lateral,
                    observation.sample_interval_sec, 0.0, 0.0,
                    cfg.prediction_course_lateral_velocity_deadband,
                    cfg.prediction_course_lateral_velocity_max,
                    observation.current_lateral});
                const int motion_sign =
                  diagnostic.applied_lateral_velocity_mps > kEps ? 1 :
                  (diagnostic.applied_lateral_velocity_mps < -kEps ? -1 : 0);
                const auto last_motion =
                  last_logged_course_lateral_motion_sign_.find(vehicle.id);
                if (
                  last_motion == last_logged_course_lateral_motion_sign_.end() ||
                  last_motion->second != motion_sign)
                {
                  RCLCPP_INFO(
                    rclcpp::get_logger("mpc_controller"),
                    "V2X course lateral motion: id=%s, direction=%s, "
                    "d_prev=%.2f, d_now=%.2f, raw_d_dot=%.2f, "
                    "applied_d_dot=%.2f, dt=%.2f",
                    vehicle.id.c_str(),
                    motion_sign > 0 ? "left" : (motion_sign < 0 ? "right" : "steady"),
                    observation.previous_lateral, observation.current_lateral,
                    diagnostic.raw_lateral_velocity_mps,
                    diagnostic.applied_lateral_velocity_mps,
                    observation.sample_interval_sec);
                  last_logged_course_lateral_motion_sign_[vehicle.id] = motion_sign;
                }
              }
            }
          }
        } catch (const std::invalid_argument &) {
          // An invalid path or V2X sample affects only this optional prediction.
          // The per-horizon Cartesian constant-velocity fallback remains available.
        }
      }
    }

    // A staggered start row does not put both boundary vehicles in the same
    // instantaneous Frenet cross-section.  For start-grid corridor selection only,
    // keep the two nearest non-rear vehicles as longitudinally persistent lateral
    // boundaries.  This exposes the three physical choices (wall-car, car-car,
    // car-wall) to one comparison.  Normal execution planning continues to use the
    // real vehicle length and the locked corridor centre, so this does not enlarge
    // obstacles during the race.
    struct StartGridCourseProjection
    {
      double forward_distance{};
      double lateral{};
      double along_track_speed{};
    };
    std::unordered_map<std::string, StartGridCourseProjection> start_grid_course_projections;
    std::unordered_set<std::string> start_grid_persistent_vehicle_ids;
    const double start_grid_span =
      prefer_short_lateral_path ?
      std::max(0.0, start_grid_inter_vehicle_longitudinal_span) : 0.0;
    const double start_grid_lookbehind =
      prefer_short_lateral_path ?
      std::max(0.0, start_grid_inter_vehicle_lookbehind_distance) : 0.0;
    if (start_grid_span > kEps && vehicles.size() >= 2U) {
      struct ForwardVehicle
      {
        double longitudinal{};
        std::string id;
      };
      std::vector<ForwardVehicle> forward_vehicles;
      std::vector<v2x_overtake_core::CoursePoint> course_path;
      course_path.reserve(static_cast<std::size_t>(model.reference_path->n_waypoints));
      for (int waypoint_id = 0; waypoint_id < model.reference_path->n_waypoints; ++waypoint_id) {
        const auto & waypoint = model.reference_path->get_waypoint(waypoint_id);
        course_path.push_back({waypoint.x, waypoint.y});
      }
      for (const auto & vehicle : vehicles) {
        const double age = std::max(0.0, now_sec - vehicle.stamp_sec);
        const double pred_x = vehicle.x + vehicle.vx * age;
        const double pred_y = vehicle.y + vehicle.vy * age;
        const auto projection = v2x_overtake_core::project_forward_course_progress(
          course_path,
          v2x_overtake_core::ForwardCourseProjectionRequest{
            static_cast<std::size_t>(std::max(0, ref_wp_id)),
            model.reference_path->circular,
            model.temporal_state.x,
            model.temporal_state.y,
            pred_x,
            pred_y,
            vehicle.vx,
            vehicle.vy,
            start_grid_lookbehind,
            2.0 * start_grid_span,
            10.0,
            std::nullopt,
            std::numeric_limits<double>::infinity()});
        if (
          !projection.valid ||
          !v2x_overtake_core::is_start_grid_boundary_candidate(
            v2x_overtake_core::StartGridBoundaryCandidateRequest{
              projection.forward_distance_m, start_grid_lookbehind, 2.0 * start_grid_span}))
        {
          continue;
        }
        start_grid_course_projections.emplace(
          vehicle.id,
          StartGridCourseProjection{
            projection.forward_distance_m,
            projection.lateral_m,
            projection.along_track_speed_mps});
        forward_vehicles.push_back({projection.forward_distance_m, vehicle.id});
      }
      std::sort(
        forward_vehicles.begin(), forward_vehicles.end(),
        [](const ForwardVehicle & lhs, const ForwardVehicle & rhs) {
          return lhs.longitudinal < rhs.longitudinal;
        });
      for (std::size_t i = 0; i < std::min<std::size_t>(2U, forward_vehicles.size()); ++i) {
        start_grid_persistent_vehicle_ids.insert(forward_vehicles[i].id);
      }
      if (start_grid_persistent_vehicle_ids.size() < 2U) {
        start_grid_persistent_vehicle_ids.clear();
      }
    }

    if (!allow_vehicle_vehicle_gap && should_block_multi_front_gap(model, ref_wp_id, base_lb, base_ub, vehicles)) {
      output.active = true;
      output.feasible = false;
      output.reject_reason = "multi-front policy";
      output.reject_gate = "multi-front-policy";
      output.target_velocity_limit = std::max(0.0, cfg.no_gap_target_velocity);
      if (update_last_target) {
        std::lock_guard<std::mutex> lock(mutex_);
        last_target_ey_.reset();
      }
      return output;
    }

    output.lb.assign(N, 0.0);
    output.ub.assign(N, 0.0);
    output.target_ey.assign(N, 0.0);
    output.target_active.assign(N, false);
    bool any_obstacle_in_horizon = false;
    bool feasible = true;
    double selected_first_target = desired_ey;
    bool first_target_selected = false;
    std::size_t selected_first_target_index = 0;
    double path_prediction_time = 0.0;
    std::optional<std::pair<std::string, std::string>> selected_vehicle_vehicle_gap =
      locked_vehicle_vehicle_gap;
    const bool external_vehicle_vehicle_gap_lock = locked_vehicle_vehicle_gap.has_value();
    double current_vehicle_vehicle_corridor_distance = 0.0;
    double horizon_course_distance = 0.0;
    double course_prediction_horizon_distance = 0.0;
    bool forced_side_transition_crossing_started = false;
    bool forced_side_transition_requested_side_reached = false;
    bool forced_side_transition_certified = false;
    double forced_side_transition_side_reached_distance_m =
      std::numeric_limits<double>::quiet_NaN();
    // V2X has no target yaw. Keep the configured aggressive circular radius for a car-car slot,
    // but use each rectangle's half-diagonal when deciding whether a wall-car slot can really
    // contain ego. The extra inflation is attached to the vehicle boundary and applied only when
    // the opposite boundary is a wall.
    const double start_grid_ego_lateral_half_extent = prefer_short_lateral_path ?
      v2x_overtake_core::conservative_rectangle_lateral_half_extent(
        model.length, model.width) : 0.0;
    const double target_half_width = std::max(
      0.0, cfg.vehicle_radius - 0.5 * std::max(0.0, model.width));
    const double start_grid_target_lateral_half_extent = prefer_short_lateral_path ?
      v2x_overtake_core::conservative_rectangle_lateral_half_extent(
        cfg.vehicle_length, 2.0 * target_half_width) : 0.0;
    const double start_grid_wall_vehicle_body_radius =
      start_grid_ego_lateral_half_extent + start_grid_target_lateral_half_extent;
    const double corridor_wall_clearance = prefer_short_lateral_path ?
      std::max(cfg.wall_clearance_margin, start_grid_ego_lateral_half_extent) :
      cfg.wall_clearance_margin;

    for (int i = 0; i < N; ++i) {
      const LateralInterval base{base_lb[i], base_ub[i]};
      output.lb[i] = base.lower;
      output.ub[i] = base.upper;
      output.target_ey[i] = base.center();
      if (base.width() <= kEps) {
        continue;
      }

      const auto & waypoint = model.reference_path->get_waypoint(ref_wp_id + i);
      if (i == 0) {
        course_prediction_horizon_distance = std::hypot(
          waypoint.x - model.temporal_state.x,
          waypoint.y - model.temporal_state.y);
      } else {
        const double segment_distance = waypoint.distance_to(
          model.reference_path->get_waypoint(ref_wp_id + i - 1));
        horizon_course_distance += segment_distance;
        course_prediction_horizon_distance += segment_distance;
      }
      double horizon_t = std::min(static_cast<double>(i + 1) * model.Ts, cfg.prediction_time);
      if (cfg.prediction_use_path_time) {
        double segment_distance = 0.0;
        if (i == 0) {
          segment_distance = std::hypot(
            waypoint.x - model.temporal_state.x,
            waypoint.y - model.temporal_state.y);
        } else {
          segment_distance = waypoint.distance_to(
            model.reference_path->get_waypoint(ref_wp_id + i - 1));
        }
        const double prediction_ego_speed =
          prediction_ego_speed_override_mps.has_value() &&
          std::isfinite(prediction_ego_speed_override_mps.value()) ?
          prediction_ego_speed_override_mps.value() : waypoint.v_ref;
        path_prediction_time = v2x_overtake_core::advance_prediction_time(
          v2x_overtake_core::PredictionTimeRequest{
            path_prediction_time, segment_distance,
            std::min(std::max(0.0, prediction_ego_speed), cfg.prediction_max_ego_speed),
            cfg.prediction_min_ego_speed, cfg.prediction_time});
        horizon_t = path_prediction_time;
      }
      std::vector<OccupiedInterval> occupied;
      for (const auto & vehicle : vehicles) {
        const double age = std::max(0.0, now_sec - vehicle.stamp_sec);
        const double pred_x = vehicle.x + vehicle.vx * (age + horizon_t);
        const double pred_y = vehicle.y + vehicle.vy * (age + horizon_t);
        const double dx = pred_x - waypoint.x;
        const double dy = pred_y - waypoint.y;
        const double fallback_longitudinal =
          std::cos(waypoint.psi) * dx + std::sin(waypoint.psi) * dy;
        const double fallback_lateral =
          -std::sin(waypoint.psi) * dx + std::cos(waypoint.psi) * dy;
        const auto course_projection = course_aligned_projections.find(vehicle.id);
        const auto course_prediction =
          v2x_overtake_core::resolve_course_aligned_prediction(
          v2x_overtake_core::CourseAlignedPredictionRequest{
            cfg.prediction_use_course_progress,
            course_projection != course_aligned_projections.end(),
            course_projection != course_aligned_projections.end() ?
            course_projection->second.forward_distance_m : 0.0,
            course_projection != course_aligned_projections.end() ?
            course_projection->second.lateral_m : 0.0,
            course_projection != course_aligned_projections.end() ?
            course_projection->second.along_track_speed_mps : 0.0,
            horizon_t,
            course_prediction_horizon_distance,
            fallback_longitudinal,
            fallback_lateral});
        double longitudinal = course_prediction.longitudinal_m;
        const auto course_lateral_observation =
          course_lateral_observations.find(vehicle.id);
        const auto course_lateral_prediction =
          v2x_overtake_core::resolve_course_lateral_prediction(
          v2x_overtake_core::CourseLateralPredictionRequest{
            cfg.prediction_use_course_lateral_velocity,
            course_lateral_observation != course_lateral_observations.end(),
            course_lateral_observation != course_lateral_observations.end(),
            course_lateral_observation != course_lateral_observations.end() ?
            course_lateral_observation->second.current_lateral : 0.0,
            course_lateral_observation != course_lateral_observations.end() ?
            course_lateral_observation->second.previous_lateral : 0.0,
            course_lateral_observation != course_lateral_observations.end() ?
            course_lateral_observation->second.sample_interval_sec : 0.0,
            age,
            horizon_t,
            cfg.prediction_course_lateral_velocity_deadband,
            cfg.prediction_course_lateral_velocity_max,
            course_prediction.lateral_m});
        double lateral = course_lateral_prediction.lateral_m;
        double self_distance = course_prediction.used_course_alignment ?
          std::hypot(longitudinal, lateral) :
          std::hypot(pred_x - model.temporal_state.x, pred_y - model.temporal_state.y);
        const double covariance_margin = std::max(vehicle.covariance_x, vehicle.covariance_y);
        const auto start_grid_projection = start_grid_course_projections.find(vehicle.id);
        const bool use_start_grid_course_projection =
          start_grid_persistent_vehicle_ids.count(vehicle.id) > 0U &&
          start_grid_projection != start_grid_course_projections.end();
        const bool is_locked_inter_vehicle_boundary =
          external_vehicle_vehicle_gap_lock &&
          (vehicle.id == locked_vehicle_vehicle_gap->first ||
          vehicle.id == locked_vehicle_vehicle_gap->second);
        if (use_start_grid_course_projection) {
          longitudinal = start_grid_projection->second.forward_distance +
            start_grid_projection->second.along_track_speed * horizon_t -
            horizon_course_distance;
          lateral = start_grid_projection->second.lateral;
          self_distance = std::hypot(longitudinal, lateral);
        }
        if (self_distance < cfg.self_filter_radius) {
          continue;
        }
        double obstacle_body_radius = std::max(0.0, cfg.vehicle_radius);
        if (use_start_grid_course_projection || is_locked_inter_vehicle_boundary) {
          obstacle_body_radius = std::min(
            obstacle_body_radius,
            std::max(0.0, start_grid_inter_vehicle_lateral_radius));
        }
        const double obstacle_radius =
          obstacle_body_radius + cfg.prediction_margin + covariance_margin;
        const double wall_extra_inflation = prefer_short_lateral_path ?
          std::max(0.0, start_grid_wall_vehicle_body_radius - obstacle_body_radius) : 0.0;
        double longitudinal_radius =
          0.5 * std::max(0.0, cfg.vehicle_length) + 0.5 * model.length +
          cfg.prediction_margin + covariance_margin;
        if (use_start_grid_course_projection) {
          longitudinal_radius = std::max(longitudinal_radius, 0.5 * start_grid_span);
        }
        if (std::abs(longitudinal) > longitudinal_radius) {
          continue;
        }
        if (lateral + obstacle_radius < base.lower || lateral - obstacle_radius > base.upper) {
          continue;
        }
        occupied.push_back(
          {lateral - obstacle_radius, lateral + obstacle_radius, self_distance,
            vehicle.id, vehicle.id, wall_extra_inflation, wall_extra_inflation});
      }

      if (occupied.empty() && !forced_side_transition_requested) {
        current_vehicle_vehicle_corridor_distance = 0.0;
        continue;
      }

      any_obstacle_in_horizon = any_obstacle_in_horizon || !occupied.empty();
      const auto free_intervals = compute_free_intervals(
        base, occupied, allow_vehicle_vehicle_gap, min_gap_width_override,
        corridor_wall_clearance);
      if (free_intervals.empty()) {
        feasible = false;
        output.reject_reason = allow_vehicle_vehicle_gap ?
          "gap width" : "gap width or vehicle-vehicle policy";
        output.reject_gate = allow_vehicle_vehicle_gap ?
          "no-free-corridor" : "no-wall-to-vehicle-corridor";
        output.reject_index = static_cast<std::size_t>(i);
        output.reject_distance_m = horizon_course_distance;
        output.reject_free_interval_count = free_intervals.size();
        break;
      }
      const auto pass_side_intervals = filter_by_pass_side(free_intervals, base, low_speed_pass_side);
      std::vector<GapCandidate> transition_gateway_intervals;
      auto transition_action =
        v2x_overtake_core::ForcedPassSideTransitionAction::NotForced;
      const std::vector<GapCandidate> * side_selectable_intervals = nullptr;
      if (
        forced_side_transition_requested &&
        !selected_vehicle_vehicle_gap.has_value())
      {
        transition_gateway_intervals = filter_connected_pass_side_gateways(
          free_intervals, base, desired_ey, low_speed_pass_side);
        const auto transition =
          v2x_overtake_core::resolve_forced_pass_side_transition(
          v2x_overtake_core::ForcedPassSideTransitionRequest{
            low_speed_pass_side, true,
            forced_side_transition_crossing_started,
            forced_side_transition_certified,
            !transition_gateway_intervals.empty(),
            horizon_course_distance,
            forced_pass_side_transition_distance_m});
        transition_action = transition.action;
        if (!transition.valid) {
          feasible = false;
          output.reject_reason = "invalid forced-side transition input";
          output.reject_gate = "forced-side-transition-invalid";
          output.forced_side_transition_reason = "invalid-input";
        } else if (
          transition.action ==
          v2x_overtake_core::ForcedPassSideTransitionAction::RejectDisconnected)
        {
          feasible = false;
          output.reject_reason =
            "forced pass-side transition lost its connected crossing corridor";
          output.reject_gate = "forced-side-transition-disconnected";
          output.forced_side_transition_reason = "crossing-disconnected";
          output.forced_side_transition_first_disconnect_index =
            static_cast<std::size_t>(i);
          output.forced_side_transition_first_disconnect_distance_m =
            horizon_course_distance;
        }
        if (!feasible) {
          output.reject_index = static_cast<std::size_t>(i);
          output.reject_distance_m = horizon_course_distance;
          output.reject_free_interval_count = free_intervals.size();
          break;
        }

        if (
          transition.action ==
          v2x_overtake_core::ForcedPassSideTransitionAction::KeepConnectedPrefix)
        {
          side_selectable_intervals = &free_intervals;
          ++output.forced_side_transition_prefix_samples;
          output.forced_side_transition_reason = "connected-prefix";
        } else if (
          transition.action ==
          v2x_overtake_core::ForcedPassSideTransitionAction::BeginCrossing)
        {
          side_selectable_intervals = &transition_gateway_intervals;
          forced_side_transition_crossing_started = true;
          output.forced_side_transition_gateway_found = true;
          output.forced_side_transition_crossing_started = true;
          output.forced_side_transition_gateway_index = static_cast<std::size_t>(i);
          output.forced_side_transition_gateway_distance_m = horizon_course_distance;
          output.forced_side_transition_reason = "crossing-started";
        } else if (
          transition.action ==
          v2x_overtake_core::ForcedPassSideTransitionAction::ContinueCrossing)
        {
          side_selectable_intervals = &transition_gateway_intervals;
          output.forced_side_transition_crossing_started = true;
          output.forced_side_transition_reason = "crossing-continued";
        } else {
          if (pass_side_intervals.empty()) {
            feasible = false;
            output.reject_reason = "pass-side gap unavailable after transition gateway";
            output.reject_gate = "forced-side-empty-after-gateway";
            output.reject_index = static_cast<std::size_t>(i);
            output.reject_distance_m = horizon_course_distance;
            output.reject_free_interval_count = free_intervals.size();
            output.forced_side_transition_reason = "side-lost-after-gateway";
            break;
          }
          side_selectable_intervals = &pass_side_intervals;
          output.forced_side_transition_reason = "side-enforced";
        }
      } else {
        if (
          low_speed_pass_side != 0 && pass_side_intervals.empty() &&
          !selected_vehicle_vehicle_gap.has_value())
        {
          feasible = false;
          output.reject_reason = "pass-side gap unavailable";
          output.reject_gate = "forced-side-empty";
          output.reject_index = static_cast<std::size_t>(i);
          output.reject_distance_m = horizon_course_distance;
          output.reject_free_interval_count = free_intervals.size();
          break;
        }
        side_selectable_intervals =
          selected_vehicle_vehicle_gap.has_value() || pass_side_intervals.empty() ?
          &free_intervals : &pass_side_intervals;
      }
      std::vector<GapCandidate> locked_pair_intervals;
      if (selected_vehicle_vehicle_gap.has_value()) {
        for (const auto & candidate : *side_selectable_intervals) {
          if (
            candidate.is_vehicle_vehicle_gap() &&
            candidate.lower_vehicle_id == selected_vehicle_vehicle_gap->first &&
            candidate.upper_vehicle_id == selected_vehicle_vehicle_gap->second)
          {
            locked_pair_intervals.push_back(candidate);
          }
        }
        if (locked_pair_intervals.empty()) {
          if (external_vehicle_vehicle_gap_lock) {
            for (const auto & candidate : *side_selectable_intervals) {
              if (
                locked_corridor_target_ey.has_value() &&
                candidate.interval.lower - kEps <= locked_corridor_target_ey.value() &&
                locked_corridor_target_ey.value() <= candidate.interval.upper + kEps)
              {
                locked_pair_intervals.push_back(candidate);
              }
            }
            if (locked_pair_intervals.empty()) {
              feasible = false;
              output.reject_reason = "locked vehicle-vehicle corridor unavailable";
              output.reject_gate = "locked-corridor-missing";
              output.reject_index = static_cast<std::size_t>(i);
              output.reject_distance_m = horizon_course_distance;
              output.reject_free_interval_count = free_intervals.size();
              break;
            }
          } else {
            selected_vehicle_vehicle_gap.reset();
            current_vehicle_vehicle_corridor_distance = 0.0;
          }
        }
      }
      const auto & selectable_intervals =
        selected_vehicle_vehicle_gap.has_value() && !locked_pair_intervals.empty() ?
        locked_pair_intervals : *side_selectable_intervals;
      double selection_desired_ey = desired_ey;
      const bool prefer_locked_target = use_low_speed_target_lock && low_speed_locked_target_ey.has_value();
      if (prefer_locked_target) {
        selection_desired_ey = low_speed_locked_target_ey.value();
      }
      const bool prefer_wide_gap =
        allow_vehicle_vehicle_gap && low_speed_pass_side == 0 && !prefer_locked_target &&
        !prefer_short_lateral_path;
      if (prefer_short_lateral_path && !first_target_selected) {
        std::ostringstream candidates;
        for (std::size_t candidate_index = 0;
          candidate_index < selectable_intervals.size(); ++candidate_index)
        {
          const auto & candidate = selectable_intervals[candidate_index];
          if (candidate_index > 0U) {
            candidates << ";";
          }
          candidates << (candidate.is_vehicle_vehicle_gap() ? "vehicle-vehicle" : "wall-vehicle")
                     << "@" << candidate.interval.center()
                     << "/" << candidate.interval.width();
          if (candidate.is_vehicle_vehicle_gap()) {
            candidates << "[" << candidate.lower_vehicle_id
                       << "," << candidate.upper_vehicle_id << "]";
          }
        }
        output.corridor_candidates = candidates.str();
      }
      const auto selected = select_interval(
        selectable_intervals, selection_desired_ey, prefer_wide_gap, prefer_locked_target,
        prefer_short_lateral_path);
      if (
        prefer_short_lateral_path && !selected_vehicle_vehicle_gap.has_value() &&
        selected.is_vehicle_vehicle_gap())
      {
        selected_vehicle_vehicle_gap =
          std::make_pair(selected.lower_vehicle_id, selected.upper_vehicle_id);
      }
      if (allow_vehicle_vehicle_gap && low_speed_pass_side == 0) {
        low_speed_pass_side = infer_pass_side_sign(base, selected.interval);
        if (low_speed_pass_side == 0 && prefer_short_lateral_path) {
          const double relative_target = selected.interval.center() - model.spatial_state.e_y;
          low_speed_pass_side = relative_target < -kEps ? -1 : 1;
        }
      }
      if ((allow_vehicle_vehicle_gap || forced_pass_side_sign != 0) && output.pass_side_sign == 0) {
        output.pass_side_sign = low_speed_pass_side;
      }
      const auto & adjusted = selected.interval;
      output.lb[i] = adjusted.lower;
      output.ub[i] = adjusted.upper;
      output.target_ey[i] = prefer_locked_target ?
        clip(low_speed_locked_target_ey.value(), adjusted.lower, adjusted.upper) :
        forced_side_transition_requested &&
        transition_action !=
        v2x_overtake_core::ForcedPassSideTransitionAction::KeepConnectedPrefix ?
        forced_pass_side_target(adjusted, base, low_speed_pass_side) :
        select_target_ey(selected, allow_vehicle_vehicle_gap);
      output.target_active[i] = true;
      desired_ey = output.target_ey[i];
      if (
        forced_side_transition_requested &&
        forced_side_transition_crossing_started &&
        !forced_side_transition_certified)
      {
        const auto certificate =
          v2x_overtake_core::certify_forced_pass_side_transition(
          v2x_overtake_core::ForcedPassSideTransitionCertificateRequest{
            low_speed_pass_side,
            forced_side_transition_crossing_started,
            forced_side_transition_requested_side_reached,
            forced_side_transition_certified,
            output.target_ey[i],
            base.center(),
            horizon_course_distance,
            forced_side_transition_side_reached_distance_m,
            std::max(kEps, std::max(0.0, forced_pass_side_transition_min_shift_m)),
            forced_pass_side_transition_distance_m});
        if (!certificate.valid) {
          feasible = false;
          output.reject_reason = "invalid forced-side transition certificate input";
          output.reject_gate = "forced-side-transition-certificate-invalid";
          output.reject_index = static_cast<std::size_t>(i);
          output.reject_distance_m = horizon_course_distance;
          output.forced_side_transition_reason = "certificate-invalid";
          break;
        }
        forced_side_transition_requested_side_reached =
          certificate.requested_side_reached;
        forced_side_transition_side_reached_distance_m =
          certificate.side_reached_distance_m;
        forced_side_transition_certified = certificate.transition_certified;
        if (certificate.requested_side_reached_now) {
          output.forced_side_transition_requested_side_reached = true;
          output.forced_side_transition_side_reached_index =
            static_cast<std::size_t>(i);
          output.forced_side_transition_side_reached_distance_m =
            horizon_course_distance;
          output.forced_side_transition_reason = "requested-side-reached";
        }
        if (certificate.requested_side_reached) {
          output.forced_side_transition_certified_until_index =
            static_cast<std::size_t>(i);
          output.forced_side_transition_certified_until_distance_m =
            horizon_course_distance;
          if (certificate.transition_certified) {
            output.forced_side_transition_certified = true;
            output.forced_side_transition_reason = "connected-crossing-certified";
          }
        }
      }
      if (
        forced_side_transition_requested &&
        forced_side_transition_certified)
      {
        output.forced_side_transition_certified_until_index =
          static_cast<std::size_t>(i);
        output.forced_side_transition_certified_until_distance_m =
          horizon_course_distance;
      }
      if (!first_target_selected) {
        selected_first_target = output.target_ey[i];
        selected_first_target_index = static_cast<std::size_t>(i);
        first_target_selected = true;
        output.vehicle_vehicle_corridor = selected.is_vehicle_vehicle_gap();
        output.lower_boundary_vehicle_id = selected.lower_vehicle_id;
        output.upper_boundary_vehicle_id = selected.upper_vehicle_id;
        output.selected_corridor_width = adjusted.width();
      }
      if (selected.is_vehicle_vehicle_gap()) {
        const auto & next_waypoint = model.reference_path->get_waypoint(ref_wp_id + i + 1);
        current_vehicle_vehicle_corridor_distance += next_waypoint.distance_to(waypoint);
        output.vehicle_vehicle_corridor_distance = std::max(
          output.vehicle_vehicle_corridor_distance,
          current_vehicle_vehicle_corridor_distance);
      } else {
        current_vehicle_vehicle_corridor_distance = 0.0;
      }
    }

    if (
      feasible && forced_side_transition_requested &&
      !forced_side_transition_certified)
    {
      feasible = false;
      output.reject_reason = forced_side_transition_crossing_started ?
        "forced pass-side crossing was not certified in planning horizon" :
        "forced pass-side transition gateway absent from planning horizon";
      output.reject_gate = forced_side_transition_crossing_started ?
        "forced-side-transition-uncertified" :
        "forced-side-transition-incomplete";
      output.reject_index = output.target_active.empty() ?
        0U : output.target_active.size() - 1U;
      output.reject_distance_m = horizon_course_distance;
      output.forced_side_transition_reason =
        !forced_side_transition_crossing_started ?
        "horizon-ended-before-gateway" :
        (!forced_side_transition_requested_side_reached ?
        "horizon-ended-before-side-reached" :
        "horizon-ended-before-connected-certificate");
    }

    if (!any_obstacle_in_horizon) {
      if (allow_vehicle_vehicle_gap && update_last_target && low_speed_pass_side != 0) {
        output.active = true;
        output.feasible = true;
        apply_low_speed_pass_side_hold(output, model.spatial_state.e_y, low_speed_pass_side);
        {
          std::lock_guard<std::mutex> lock(mutex_);
          low_speed_locked_side_sign_ = low_speed_pass_side;
          if (!output.target_ey.empty()) {
            last_target_ey_ = output.target_ey.back();
          }
        }
        return output;
      }
      if (use_low_speed_target_lock && update_last_target) {
        std::lock_guard<std::mutex> lock(mutex_);
        low_speed_locked_target_ey_.reset();
      }
      return GapPlannerOutput{};
    }

    output.active = true;
    output.feasible = feasible;
    if (!feasible) {
      output.target_velocity_limit = std::max(0.0, cfg.no_gap_target_velocity);
    }

    if (feasible && use_low_speed_target_lock) {
      if (!low_speed_locked_target_ey.has_value() && first_target_selected) {
        low_speed_locked_target_ey = selected_first_target;
      }
      if (low_speed_locked_target_ey.has_value()) {
        apply_locked_target(output, low_speed_locked_target_ey.value());
      }
    }
    if (feasible && allow_vehicle_vehicle_gap && update_last_target && first_target_selected) {
      output.pass_side_sign = low_speed_pass_side;
      apply_low_speed_pass_ramp(output, model.spatial_state.e_y, selected_first_target);
    }
    if (
      feasible && !allow_vehicle_vehicle_gap && update_last_target && first_target_selected &&
      cfg.overtake_target_ramp_enabled) {
      apply_overtake_target_ramp(
        output, model.spatial_state.e_y, selected_first_target, selected_first_target_index);
    }

    {
      std::lock_guard<std::mutex> lock(mutex_);
      if (feasible && update_last_target) {
        if (use_low_speed_target_lock && low_speed_locked_target_ey.has_value()) {
          low_speed_locked_target_ey_ = low_speed_locked_target_ey.value();
          last_target_ey_ = low_speed_locked_target_ey.value();
        } else {
          last_target_ey_ = selected_first_target;
        }
        if (allow_vehicle_vehicle_gap && low_speed_pass_side != 0) {
          low_speed_locked_side_sign_ = low_speed_pass_side;
        }
      } else if (!feasible && update_last_target) {
        last_target_ey_.reset();
        if (use_low_speed_target_lock) {
          low_speed_locked_target_ey_.reset();
        }
        if (allow_vehicle_vehicle_gap) {
          low_speed_locked_side_sign_.reset();
        }
      }
    }
    return output;
  }

  V2XGapPlannerConfig cfg;

private:
  double forward_path_distance(const ReferencePath & path, const int start_wp_id, const int end_wp_id) const
  {
    if (end_wp_id <= start_wp_id) {
      return 0.0;
    }

    double distance = 0.0;
    for (int wp_id = start_wp_id; wp_id < end_wp_id; ++wp_id) {
      const auto & current = path.get_waypoint(wp_id);
      const auto & next = path.get_waypoint(wp_id + 1);
      distance += next.distance_to(current);
    }
    return distance;
  }

  bool should_block_multi_front_gap(
    const BicycleModel & model, const int ref_wp_id, const Eigen::VectorXd & base_lb,
    const Eigen::VectorXd & base_ub, const std::vector<TrackedVehicle> & vehicles) const
  {
    if (cfg.multi_front_gap_enabled || cfg.multi_front_gap_distance <= 0.0) {
      return false;
    }
    if (base_lb.size() == 0 || base_ub.size() == 0) {
      return false;
    }

    const auto & waypoint = model.reference_path->get_waypoint(ref_wp_id);
    const double cos_yaw = std::cos(waypoint.psi);
    const double sin_yaw = std::sin(waypoint.psi);
    const double lateral_range =
      std::max({std::abs(base_lb[0]), std::abs(base_ub[0]), model.width}) +
      cfg.vehicle_radius + cfg.prediction_margin;

    int front_vehicle_count = 0;
    for (const auto & vehicle : vehicles) {
      const double self_distance =
        std::hypot(vehicle.x - model.temporal_state.x, vehicle.y - model.temporal_state.y);
      if (self_distance < cfg.self_filter_radius) {
        continue;
      }

      const double dx = vehicle.x - model.temporal_state.x;
      const double dy = vehicle.y - model.temporal_state.y;
      const double longitudinal = cos_yaw * dx + sin_yaw * dy;
      const double lateral = -sin_yaw * dx + cos_yaw * dy;
      if (longitudinal <= 0.0 || longitudinal > cfg.multi_front_gap_distance) {
        continue;
      }
      if (std::abs(lateral) > lateral_range) {
        continue;
      }
      ++front_vehicle_count;
      if (front_vehicle_count >= 2) {
        return true;
      }
    }
    return false;
  }

  std::vector<GapCandidate> compute_free_intervals(
    const LateralInterval & base, std::vector<OccupiedInterval> occupied,
    const bool allow_vehicle_vehicle_gap,
    const std::optional<double> min_gap_width_override,
    const double wall_clearance) const
  {
    std::vector<OccupiedInterval> merged;
    for (auto & interval : occupied) {
      interval.lower = std::max(interval.lower, base.lower);
      interval.upper = std::min(interval.upper, base.upper);
      if (interval.upper <= interval.lower) {
        continue;
      }
      merged.push_back(interval);
    }
    std::sort(
      merged.begin(), merged.end(),
      [](const OccupiedInterval & lhs, const OccupiedInterval & rhs) {
        return lhs.lower < rhs.lower;
      });

    std::vector<OccupiedInterval> compacted;
    for (const auto & interval : merged) {
      if (compacted.empty() || interval.lower > compacted.back().upper) {
        compacted.push_back(interval);
        continue;
      }
      auto & last = compacted.back();
      if (interval.upper > last.upper) {
        last.upper = interval.upper;
        last.upper_vehicle_id = interval.upper_vehicle_id;
        last.upper_wall_extra_inflation = interval.upper_wall_extra_inflation;
      }
      last.distance_from_self = std::min(last.distance_from_self, interval.distance_from_self);
    }

    std::vector<GapCandidate> free_intervals;
    double cursor = base.lower;
    bool cursor_from_vehicle = false;
    double cursor_vehicle_distance = std::numeric_limits<double>::infinity();
    std::string cursor_vehicle_id;
    double cursor_wall_extra_inflation = 0.0;
    for (const auto & interval : compacted) {
      if (interval.lower > cursor) {
        free_intervals.push_back(
          {{cursor, interval.lower}, cursor_from_vehicle, true, cursor_vehicle_distance,
            interval.distance_from_self, cursor_vehicle_id, interval.lower_vehicle_id,
            cursor_wall_extra_inflation, interval.lower_wall_extra_inflation});
      }
      cursor = std::max(cursor, interval.upper);
      cursor_from_vehicle = true;
      cursor_vehicle_distance = interval.distance_from_self;
      cursor_vehicle_id = interval.upper_vehicle_id;
      cursor_wall_extra_inflation = interval.upper_wall_extra_inflation;
    }
    if (cursor < base.upper) {
      free_intervals.push_back(
        {{cursor, base.upper}, cursor_from_vehicle, false, cursor_vehicle_distance,
          std::numeric_limits<double>::infinity(), cursor_vehicle_id, std::string{},
          cursor_wall_extra_inflation, 0.0});
    }

    std::vector<GapCandidate> filtered;
    const double min_width = min_gap_width_override.has_value() ?
      std::max(0.0, min_gap_width_override.value()) : std::max(0.0, cfg.min_gap_width);
    const double vehicle_vehicle_min_width = allow_vehicle_vehicle_gap ?
      min_width :
      std::max(min_width, std::max(0.0, cfg.vehicle_vehicle_gap_min_width));
    for (const auto & candidate : free_intervals) {
      double required_width = min_width;
      if (candidate.is_vehicle_vehicle_gap()) {
        if (!cfg.vehicle_vehicle_gap_enabled && !allow_vehicle_vehicle_gap) {
          continue;
        }
        required_width = vehicle_vehicle_min_width;
        if (
          !allow_vehicle_vehicle_gap && cfg.vehicle_vehicle_gap_min_distance > 0.0 &&
          candidate.nearest_vehicle_distance() < cfg.vehicle_vehicle_gap_min_distance) {
          continue;
        }
      }
      const bool wall_vehicle_corridor =
        candidate.lower_is_vehicle != candidate.upper_is_vehicle;
      double vehicle_extra_inflation = 0.0;
      if (wall_vehicle_corridor) {
        vehicle_extra_inflation = candidate.lower_is_vehicle ?
          candidate.lower_vehicle_wall_extra_inflation :
          candidate.upper_vehicle_wall_extra_inflation;
      }
      const auto geometry = v2x_overtake_core::evaluate_wall_corridor_geometry(
        v2x_overtake_core::WallCorridorGeometryRequest{
          candidate.interval.lower, candidate.interval.upper,
          candidate.lower_is_vehicle, candidate.upper_is_vehicle,
          vehicle_extra_inflation, std::max(0.0, wall_clearance), required_width});
      if (geometry.feasible) {
        auto adjusted_candidate = candidate;
        adjusted_candidate.interval = {geometry.lower, geometry.upper};
        filtered.push_back(std::move(adjusted_candidate));
      }
    }
    return filtered;
  }

  void apply_locked_target(GapPlannerOutput & output, const double target_ey) const
  {
    for (std::size_t i = 0; i < output.target_ey.size(); ++i) {
      if (i >= output.lb.size() || i >= output.ub.size()) {
        continue;
      }
      if (i >= output.target_active.size() || !output.target_active[i]) {
        continue;
      }
      if (output.ub[i] - output.lb[i] <= kEps) {
        continue;
      }
      output.target_ey[i] = clip(target_ey, output.lb[i], output.ub[i]);
    }
  }

  int low_speed_pass_side_sign() const
  {
    if (cfg.low_speed_pass_side == "left") {
      return 1;
    }
    if (cfg.low_speed_pass_side == "right") {
      return -1;
    }
    return 0;
  }

  int infer_pass_side_sign(const LateralInterval & base, const LateralInterval & selected) const
  {
    const double delta = selected.center() - base.center();
    if (delta > kEps) {
      return 1;
    }
    if (delta < -kEps) {
      return -1;
    }
    return 0;
  }

  std::vector<GapCandidate> filter_by_pass_side(
    const std::vector<GapCandidate> & intervals, const LateralInterval & base,
    const int pass_side_sign) const
  {
    if (pass_side_sign == 0) {
      return {};
    }

    std::vector<GapCandidate> filtered;
    const double base_center = base.center();
    for (const auto & candidate : intervals) {
      const double delta = candidate.interval.center() - base_center;
      if ((pass_side_sign > 0 && delta >= -kEps) || (pass_side_sign < 0 && delta <= kEps)) {
        filtered.push_back(candidate);
      }
    }
    return filtered;
  }

  std::vector<GapCandidate> filter_connected_pass_side_gateways(
    const std::vector<GapCandidate> & intervals, const LateralInterval & base,
    const double connected_lateral, const int pass_side_sign) const
  {
    std::vector<GapCandidate> gateways;
    if (
      (pass_side_sign != -1 && pass_side_sign != 1) ||
      !std::isfinite(connected_lateral))
    {
      return gateways;
    }

    const double base_center = base.center();
    for (const auto & candidate : intervals) {
      const bool contains_connected_lateral =
        candidate.interval.lower - kEps <= connected_lateral &&
        connected_lateral <= candidate.interval.upper + kEps;
      const bool reaches_requested_side = pass_side_sign > 0 ?
        candidate.interval.upper > base_center + kEps :
        candidate.interval.lower < base_center - kEps;
      if (contains_connected_lateral && reaches_requested_side) {
        gateways.push_back(candidate);
      }
    }
    return gateways;
  }

  double forced_pass_side_target(
    const LateralInterval & interval, const LateralInterval & base,
    const int pass_side_sign) const
  {
    const double base_center = base.center();
    if (pass_side_sign > 0) {
      const double lower = std::max(interval.lower, base_center);
      return clip(0.5 * (lower + interval.upper), interval.lower, interval.upper);
    }
    if (pass_side_sign < 0) {
      const double upper = std::min(interval.upper, base_center);
      return clip(0.5 * (interval.lower + upper), interval.lower, interval.upper);
    }
    return clip(base_center, interval.lower, interval.upper);
  }

  void apply_low_speed_pass_ramp(
    GapPlannerOutput & output, const double start_ey, const double target_ey) const
  {
    const std::size_t count = std::min({output.lb.size(), output.ub.size(), output.target_ey.size()});
    if (count == 0) {
      return;
    }
    const double ramp_ratio = std::max(0.1, cfg.low_speed_pass_ramp_ratio);
    for (std::size_t i = 0; i < count; ++i) {
      if (output.ub[i] - output.lb[i] <= kEps) {
        continue;
      }
      const double progress = clip(
        (static_cast<double>(i) + 1.0) / (static_cast<double>(count) * ramp_ratio), 0.0, 1.0);
      const double ramp_target = start_ey + progress * (target_ey - start_ey);
      output.target_ey[i] = clip(ramp_target, output.lb[i], output.ub[i]);
      if (i < output.target_active.size()) {
        output.target_active[i] = true;
      }
    }
  }

  void apply_overtake_target_ramp(
    GapPlannerOutput & output, const double start_ey, const double target_ey,
    const std::size_t target_index) const
  {
    const std::size_t count =
      std::min({output.lb.size(), output.ub.size(), output.target_ey.size(), target_index + 1});
    if (count == 0) {
      return;
    }
    const double ramp_ratio = std::max(0.1, cfg.overtake_target_ramp_ratio);
    const double denominator = std::max(1.0, static_cast<double>(count) * ramp_ratio);
    for (std::size_t i = 0; i < count; ++i) {
      if (output.ub[i] - output.lb[i] <= kEps) {
        continue;
      }
      const double progress = clip((static_cast<double>(i) + 1.0) / denominator, 0.0, 1.0);
      const double ramp_target = start_ey + progress * (target_ey - start_ey);
      output.target_ey[i] = clip(ramp_target, output.lb[i], output.ub[i]);
      if (i < output.target_active.size()) {
        output.target_active[i] = true;
      }
    }
  }

  void apply_low_speed_pass_side_hold(
    GapPlannerOutput & output, const double start_ey, const int pass_side_sign) const
  {
    const std::size_t count = std::min({output.lb.size(), output.ub.size(), output.target_ey.size()});
    if (count == 0 || pass_side_sign == 0) {
      return;
    }
    for (std::size_t i = 0; i < count; ++i) {
      if (output.ub[i] - output.lb[i] <= kEps) {
        continue;
      }
      const double center = 0.5 * (output.lb[i] + output.ub[i]);
      const double side_edge = pass_side_sign > 0 ? output.ub[i] : output.lb[i];
      const double side_target = 0.5 * (center + side_edge);
      const double ramp_ratio = std::max(0.1, cfg.low_speed_pass_ramp_ratio);
      const double progress = clip(
        (static_cast<double>(i) + 1.0) / (static_cast<double>(count) * ramp_ratio), 0.0, 1.0);
      const double ramp_target = start_ey + progress * (side_target - start_ey);
      output.target_ey[i] = clip(ramp_target, output.lb[i], output.ub[i]);
      if (i < output.target_active.size()) {
        output.target_active[i] = true;
      }
    }
  }

  GapCandidate select_interval(
    const std::vector<GapCandidate> & intervals, const double desired_ey,
    const bool prefer_wide_gap, const bool prefer_containing_desired,
    const bool prefer_short_lateral_path) const
  {
    auto best = intervals.front();
    double best_score = std::numeric_limits<double>::infinity();
    for (const auto & candidate : intervals) {
      const auto & interval = candidate.interval;
      const double center = interval.center();
      const bool contains_desired =
        interval.lower - kEps <= desired_ey && desired_ey <= interval.upper + kEps;
      const double distance_to_desired = contains_desired ?
        0.0 :
        std::min(std::abs(desired_ey - interval.lower), std::abs(desired_ey - interval.upper));
      const double score = prefer_short_lateral_path ?
        v2x_overtake_core::score_start_grid_corridor(
          v2x_overtake_core::StartGridCorridorScoreRequest{
            center, interval.width(), desired_ey}) :
        prefer_containing_desired ?
        (contains_desired ? 0.0 : 1000.0) + 8.0 * distance_to_desired +
          0.2 * std::abs(center - desired_ey) - 0.2 * interval.width() :
        prefer_wide_gap ?
        0.6 * std::abs(center - desired_ey) + 0.2 * std::abs(center) - 2.0 * interval.width() :
        4.0 * std::abs(center - desired_ey) + 0.5 * std::abs(center) - 0.1 * interval.width();
      if (score < best_score) {
        best = candidate;
        best_score = score;
      }
    }
    return best;
  }

  double select_target_ey(
    const GapCandidate & selected, const bool prefer_gap_center) const
  {
    const auto & adjusted = selected.interval;
    const double center = adjusted.center();
    const double bias = prefer_gap_center ? 0.0 : clip(cfg.wall_avoidance_bias, 0.0, 1.0);
    if (bias <= kEps || adjusted.width() <= kEps) {
      return center;
    }

    const bool lower_is_wall = !selected.lower_is_vehicle;
    const bool upper_is_wall = !selected.upper_is_vehicle;
    double vehicle_side_target = center;
    const double vehicle_margin =
      std::min(std::max(0.0, cfg.vehicle_side_target_margin), adjusted.width() * 0.5);
    if (lower_is_wall && !upper_is_wall) {
      vehicle_side_target = adjusted.upper - vehicle_margin;
    } else if (upper_is_wall && !lower_is_wall) {
      vehicle_side_target = adjusted.lower + vehicle_margin;
    } else {
      return center;
    }

    const double target = (1.0 - bias) * center + bias * vehicle_side_target;
    return clip(target, adjusted.lower, adjusted.upper);
  }

  std::mutex mutex_;
  std::unordered_map<std::string, TrackedVehicle> vehicles_;
  std::optional<double> last_message_receipt_sec_;
  std::optional<double> last_message_receipt_interval_sec_;
  std::optional<double> last_message_source_stamp_sec_;
  std::optional<std::uint64_t> last_message_recovery_epoch_;
  std::uint64_t recovery_epoch_{0U};
  std::uint64_t observation_generation_{0U};
  std::size_t last_message_vehicle_count_{0U};
  std::vector<std::string> last_message_vehicle_ids_;
  overtake_core::V2XPeerIdentityTracker peer_identity_tracker_;
  bool last_message_has_empty_id_{false};
  bool last_message_has_duplicate_id_{false};
  bool last_message_has_invalid_sample_{false};
  bool track_recovery_completeness_{false};
  std::optional<double> last_target_ey_;
  std::optional<double> low_speed_locked_target_ey_;
  std::optional<int> low_speed_locked_side_sign_;
  int last_logged_local_path_side_{0};
  double last_logged_local_path_target_ey_{std::numeric_limits<double>::infinity()};
  std::optional<bool> last_logged_local_path_corridor_enforced_;
  std::unordered_map<std::string, int> last_logged_course_lateral_motion_sign_;
};

