  struct OwnedTacticalSnapshot
  {
    std::shared_ptr<ReferencePath> reference_path;
    std::shared_ptr<BicycleModel> model;
    std::shared_ptr<V2XGapPlanner> gap_planner;
    std::shared_ptr<MPC> planner;

    bool complete() const noexcept
    {
      return reference_path != nullptr && model != nullptr &&
        gap_planner != nullptr && planner != nullptr;
    }
  };

  std::optional<OwnedTacticalSnapshot> make_owned_tactical_snapshot() const
  {
    if (model == nullptr || model->reference_path == nullptr || gap_planner == nullptr) {
      return std::nullopt;
    }
    OwnedTacticalSnapshot snapshot;
    snapshot.reference_path =
      std::make_shared<ReferencePath>(*model->reference_path);
    snapshot.model = std::make_shared<BicycleModel>(*model);
    snapshot.model->reference_path = snapshot.reference_path.get();
    snapshot.model->current_waypoint =
      &snapshot.model->reference_path->waypoints.at(
      static_cast<std::size_t>(snapshot.model->wp_id));
    snapshot.gap_planner = std::shared_ptr<V2XGapPlanner>(
      gap_planner->tactical_snapshot());
    snapshot.planner = tactical_snapshot(
      snapshot.model.get(), snapshot.gap_planner.get());
    snapshot.planner->reference_path_snapshot_owner_ = snapshot.reference_path;
    return snapshot.complete() ?
      std::optional<OwnedTacticalSnapshot>{std::move(snapshot)} : std::nullopt;
  }

  void invalidate_mpcc_lite_async_results()
  {
    ++mpcc_lite_async_context_epoch_;
    mpcc_lite_async_last_accepted_result_.reset();
    const auto invalidate_mailbox = [this](auto & mailbox) {
        mailbox.context_epoch = mpcc_lite_async_context_epoch_;
        mailbox.latest_submitted_sequence = 0U;
        mailbox.latest_published_sequence = 0U;
        mailbox.latest_result.reset();
      };
    if (
      mpcc_lite_async_mailbox_ != nullptr &&
      rate_resolved_preentry_execution_shadow_mailbox_ != nullptr)
    {
      std::scoped_lock lock(
        mpcc_lite_async_mailbox_->mutex,
        rate_resolved_preentry_execution_shadow_mailbox_->mutex);
      invalidate_mailbox(*mpcc_lite_async_mailbox_);
      invalidate_mailbox(*rate_resolved_preentry_execution_shadow_mailbox_);
      return;
    }
    if (mpcc_lite_async_mailbox_ != nullptr) {
      std::lock_guard<std::mutex> lock(mpcc_lite_async_mailbox_->mutex);
      invalidate_mailbox(*mpcc_lite_async_mailbox_);
    }
    if (rate_resolved_preentry_execution_shadow_mailbox_ != nullptr) {
      std::lock_guard<std::mutex> lock(
        rate_resolved_preentry_execution_shadow_mailbox_->mutex);
      invalidate_mailbox(*rate_resolved_preentry_execution_shadow_mailbox_);
    }
  }

  void set_gap_planner(V2XGapPlanner * planner)
  {
    gap_planner = planner;
  }

  void set_overtake_static_wall_geometry(
    const recovery_footprint::OccupancyGrid * grid,
    const recovery_footprint::FootprintExtents & footprint)
  {
    overtake_static_wall_grid_snapshot_owner_.reset();
    overtake_static_wall_grid_fingerprint_ = 0U;
    if (grid != nullptr) {
      auto immutable_grid =
        std::make_shared<recovery_footprint::OccupancyGrid>(*grid);
      if (!immutable_grid->build_non_free_integral_index()) {
        throw std::invalid_argument(
                "failed to build immutable wall-grid broad-phase index");
      }
      overtake_static_wall_grid_snapshot_owner_ = std::move(immutable_grid);
      overtake_static_wall_grid_fingerprint_ =
        recovery_footprint::occupancy_grid_fingerprint(
        *overtake_static_wall_grid_snapshot_owner_);
    }
    overtake_static_wall_grid_ =
      overtake_static_wall_grid_snapshot_owner_.get();
    overtake_static_wall_footprint_ = footprint;
    physical_wall_envelope_cache_.clear();
    physical_wall_envelope_cache_lru_.clear();
    overtake_receding_horizon_scheduled_cache_.reset();
    physical_wall_envelope_cache_request_count_ = 0U;
    physical_wall_envelope_cache_hit_count_ = 0U;
    physical_wall_envelope_cache_miss_count_ = 0U;
    physical_wall_envelope_cache_evaluation_count_ = 0U;
    physical_wall_envelope_cache_scanned_pose_count_ = 0U;
  }

  PhysicalWallEnvelopeCacheTelemetry take_physical_wall_envelope_cache_telemetry()
  {
    PhysicalWallEnvelopeCacheTelemetry telemetry;
    telemetry.request_count = physical_wall_envelope_cache_request_count_;
    telemetry.hit_count = physical_wall_envelope_cache_hit_count_;
    telemetry.miss_count = physical_wall_envelope_cache_miss_count_;
    telemetry.evaluation_count = physical_wall_envelope_cache_evaluation_count_;
    telemetry.scanned_pose_count =
      physical_wall_envelope_cache_scanned_pose_count_;
    telemetry.entry_count = physical_wall_envelope_cache_.size();
    physical_wall_envelope_cache_request_count_ = 0U;
    physical_wall_envelope_cache_hit_count_ = 0U;
    physical_wall_envelope_cache_miss_count_ = 0U;
    physical_wall_envelope_cache_evaluation_count_ = 0U;
    physical_wall_envelope_cache_scanned_pose_count_ = 0U;
    return telemetry;
  }

