  GapPlanStaticWallPreflight evaluate_gap_plan_static_wall_preflight(
    const int ref_wp_id, const GapPlannerOutput & planner_output) const
  {
    GapPlanStaticWallPreflight result;
    constexpr std::size_t kTrailingExecutionSamples = 2U;
    const auto sample_contract =
      v2x_overtake_core::resolve_gap_plan_execution_sample_contract(
      planner_output.active, planner_output.feasible,
      planner_output.target_ey, planner_output.target_active,
      kTrailingExecutionSamples);
    result.execution_sample_count = sample_contract.execution_sample_count;
    result.active_sample_count = sample_contract.active_sample_count;
    result.first_active_index = sample_contract.first_active_index;
    result.last_active_index = sample_contract.last_active_index;
    result.invalid_index = sample_contract.invalid_index;
    if (!sample_contract.valid) {
      if (
        !planner_output.reject_reason.empty() &&
        (sample_contract.reason ==
        v2x_overtake_core::GapPlanExecutionSampleContractReason::PlannerInactive ||
        sample_contract.reason ==
        v2x_overtake_core::GapPlanExecutionSampleContractReason::PlannerInfeasible))
      {
        result.reason = planner_output.reject_reason;
      } else {
        result.reason = v2x_overtake_core::to_string(sample_contract.reason);
      }
      return result;
    }
    if (
      overtake_static_wall_grid_ == nullptr ||
      !overtake_static_wall_footprint_.valid())
    {
      result.reason = "static wall geometry unavailable";
      return result;
    }
    if (!actual_wall_monitor_pose_.has_value()) {
      result.reason = "raw pose unavailable";
      return result;
    }

    auto clearance_footprint = overtake_static_wall_footprint_;
    const double wall_clearance_margin =
      std::max(0.0, cfg.v2x_gap.wall_clearance_margin);
    clearance_footprint.left_extent_m += wall_clearance_margin;
    clearance_footprint.right_extent_m += wall_clearance_margin;

    std::vector<recovery_footprint::Pose2D> path;
    std::vector<double> execution_target_ey;
    path.reserve(sample_contract.execution_sample_count + 1U);
    execution_target_ey.reserve(sample_contract.execution_sample_count);
    path.push_back(actual_wall_monitor_pose_.value());
    for (std::size_t index = 0U;
      index < sample_contract.execution_sample_count; ++index)
    {
      const auto & waypoint =
        model->reference_path->get_waypoint(ref_wp_id + static_cast<int>(index) + 1);
      const double left_x = -std::sin(waypoint.psi);
      const double left_y = std::cos(waypoint.psi);
      const bool lateral_target_active =
        planner_output.target_active.empty() ||
        (index < planner_output.target_active.size() &&
        planner_output.target_active[index]);
      const bool reference_bounds_available =
        index < planner_output.lb.size() && index < planner_output.ub.size() &&
        std::isfinite(planner_output.lb[index]) &&
        std::isfinite(planner_output.ub[index]) &&
        planner_output.lb[index] <= planner_output.ub[index];
      if (!lateral_target_active && !reference_bounds_available) {
        result.invalid_index = index;
        result.reason = "inactive reference bounds unavailable";
        return result;
      }
      double target_ey = planner_output.target_ey[index];
      if (reference_bounds_available) {
        const double center_ey =
          0.5 * (planner_output.lb[index] + planner_output.ub[index]);
        const double base_reference = clip(
          cfg.center_bias * center_ey,
          planner_output.lb[index], planner_output.ub[index]);
        target_ey = lateral_target_active ?
          (1.0 - cfg.v2x_gap.target_bias) * base_reference +
          cfg.v2x_gap.target_bias * planner_output.target_ey[index] :
          base_reference;
        target_ey = clip(
          target_ey, planner_output.lb[index], planner_output.ub[index]);
      }
      execution_target_ey.push_back(target_ey);
      path.push_back(
        recovery_footprint::Pose2D{
          waypoint.x + target_ey * left_x,
          waypoint.y + target_ey * left_y,
          waypoint.psi});
    }
    // A changing lateral target rotates the vehicle relative to the reference
    // path.  Using waypoint.psi for every sample underestimates the swept
    // footprint exactly where an escape path turns toward a wall.  Preserve
    // the measured yaw at the current pose and derive planned yaws from the
    // candidate path tangent.
    for (std::size_t index = 1U; index < path.size(); ++index) {
      const std::size_t next_index = std::min(index + 1U, path.size() - 1U);
      const std::size_t previous_index = next_index == index ? index - 1U : index;
      const double dx = path[next_index].x_m - path[previous_index].x_m;
      const double dy = path[next_index].y_m - path[previous_index].y_m;
      if (std::hypot(dx, dy) > 1e-6) {
        path[index].yaw_rad = std::atan2(dy, dx);
      }
    }

    const double swept_step_m = std::max(
      1e-3, std::min(0.10, 0.5 * overtake_static_wall_grid_->resolution_m));
    const double maximum_margin_escape_distance_m =
      std::max(0.0, cfg.v2x_gap.wall_margin_escape_max_distance);
    const double minimum_centerward_shift_m =
      std::max(0.0, cfg.v2x_gap.wall_margin_escape_min_centerward_shift);
    const double initial_absolute_lateral_m =
      std::abs(model->spatial_state.e_y);
    double previous_absolute_lateral_m = initial_absolute_lateral_m;
    double candidate_distance_m = 0.0;
    bool centerward_non_worsening = true;
    bool centerward_progress = false;
    for (std::size_t index = 0U; index < execution_target_ey.size(); ++index) {
      candidate_distance_m += std::hypot(
        path[index + 1U].x_m - path[index].x_m,
        path[index + 1U].y_m - path[index].y_m);
      if (
        candidate_distance_m > maximum_margin_escape_distance_m + kEps)
      {
        break;
      }
      const double absolute_target_lateral_m =
        std::abs(execution_target_ey[index]);
      if (absolute_target_lateral_m > previous_absolute_lateral_m + 0.05) {
        centerward_non_worsening = false;
        break;
      }
      centerward_progress =
        centerward_progress ||
        absolute_target_lateral_m + minimum_centerward_shift_m <=
        initial_absolute_lateral_m;
      previous_absolute_lateral_m = absolute_target_lateral_m;
    }
    const bool allow_initial_margin_escape =
      cfg.v2x_gap.wall_margin_escape_enabled && centerward_non_worsening &&
      centerward_progress;
    const auto clearance =
      recovery_footprint::evaluate_clearance_margin_escape_path(
      *overtake_static_wall_grid_, overtake_static_wall_footprint_,
      clearance_footprint, path, swept_step_m, allow_initial_margin_escape,
      maximum_margin_escape_distance_m);
    result.feasible = clearance.valid && clearance.clear;
    result.margin_escape_used = clearance.margin_escape_used;
    result.checked_pose_count = clearance.margin_checked_pose_count;
    result.physical_checked_pose_count =
      clearance.physical_checked_pose_count;
    result.initial_margin_contact_count =
      clearance.initial_margin_contact_count;
    result.maximum_margin_contact_count =
      clearance.maximum_margin_contact_count;
    result.final_margin_contact_count =
      clearance.final_margin_contact_count;
    result.margin_clear_path_index = clearance.margin_clear_path_index;
    result.margin_clear_distance_m = clearance.margin_clear_distance_m;
    result.mode = result.feasible ?
      (clearance.margin_escape_used ? "margin-escape" : "clear") :
      "rejected";
    if (result.feasible) {
      result.reason = clearance.margin_escape_used ?
        "initial clearance overlap restored by bounded centerward escape" :
        "none";
    } else {
      std::ostringstream reason;
      reason << recovery_footprint::to_string(clearance.reason)
             << ", physical="
             << recovery_footprint::to_string(clearance.physical_reason)
             << ", margin="
             << recovery_footprint::to_string(clearance.margin_reason)
             << ", centerward=" << (allow_initial_margin_escape ? 1 : 0);
      result.reason = reason.str();
    }
    return result;
  }

  GapPlannerOutput plan_low_speed_local_path_with_static_wall_preflight(
    const int ref_wp_id, const int N, const Eigen::VectorXd & lb,
    const Eigen::VectorXd & ub, const double now_sec, const bool update_last_target,
    const int forced_pass_side_sign = 0)
  {
    if (gap_planner == nullptr) {
      GapPlannerOutput output;
      output.reject_reason = "gap planner unavailable";
      output.reject_gate = "planner-unavailable";
      return output;
    }

    auto candidate = gap_planner->plan_stopped_vehicle_local_path(
      *model, ref_wp_id, N, lb, ub, now_sec, cfg.v2x_behavior, false,
      forced_pass_side_sign);
    auto preflight = evaluate_gap_plan_static_wall_preflight(ref_wp_id, candidate);
    const int primary_side = candidate.pass_side_sign;
    const std::string primary_reason = preflight.reason;
    const std::size_t primary_checked_pose_count = preflight.checked_pose_count;
    bool static_wall_preflight_evaluated =
      candidate.active && candidate.feasible;
    bool alternate_selected = false;

    const bool auto_side =
      cfg.v2x_gap.low_speed_pass_side == "auto" && forced_pass_side_sign == 0;
    if (
      v2x_overtake_core::should_try_alternate_low_speed_pass_side(
        auto_side, preflight.feasible, primary_side))
    {
      auto alternate = gap_planner->plan_stopped_vehicle_local_path(
        *model, ref_wp_id, N, lb, ub, now_sec, cfg.v2x_behavior, false, -primary_side);
      const auto alternate_preflight =
        evaluate_gap_plan_static_wall_preflight(ref_wp_id, alternate);
      if (alternate_preflight.feasible) {
        candidate = std::move(alternate);
        preflight = alternate_preflight;
        alternate_selected = true;
      } else {
        const bool alternate_static_wall_preflight_evaluated =
          alternate.active && alternate.feasible;
        static_wall_preflight_evaluated =
          static_wall_preflight_evaluated ||
          alternate_static_wall_preflight_evaluated;
        if (static_wall_preflight_evaluated) {
          preflight.reason =
            primary_reason + "; alternate " +
            low_speed_pass_side_name(-primary_side) + ": " +
            alternate_preflight.reason;
          preflight.checked_pose_count =
            primary_checked_pose_count + alternate_preflight.checked_pose_count;
        }
      }
    }

    if (!preflight.feasible) {
      if (!static_wall_preflight_evaluated) {
        return candidate;
      }
      candidate.feasible = false;
      candidate.target_velocity_limit =
        std::max(0.0, cfg.v2x_gap.no_gap_target_velocity);
      candidate.reject_reason = "static wall preflight: " + preflight.reason;
      candidate.reject_gate = "static-wall-preflight";
      const std::string signature =
        std::to_string(primary_side) + ":" + preflight.reason;
      if (
        signature != last_low_speed_static_wall_preflight_log_signature_ ||
        !std::isfinite(last_low_speed_static_wall_preflight_log_sec_) ||
        now_sec - last_low_speed_static_wall_preflight_log_sec_ >= 1.0)
      {
        RCLCPP_WARN(
          rclcpp::get_logger("mpc_controller"),
          "Low-speed static wall preflight rejected: side=%s, reason=%s, checked=%zu",
          low_speed_pass_side_name(primary_side), preflight.reason.c_str(),
          preflight.checked_pose_count);
        last_low_speed_static_wall_preflight_log_signature_ = signature;
        last_low_speed_static_wall_preflight_log_sec_ = now_sec;
      }
      return candidate;
    }

    if (alternate_selected) {
      const std::string signature =
        std::to_string(primary_side) + "->" + std::to_string(candidate.pass_side_sign);
      if (signature != last_low_speed_static_wall_preflight_log_signature_) {
        RCLCPP_INFO(
          rclcpp::get_logger("mpc_controller"),
          "Low-speed static wall preflight switched side: %s -> %s, "
          "primary_reason=%s, selected_checked=%zu",
          low_speed_pass_side_name(primary_side),
          low_speed_pass_side_name(candidate.pass_side_sign),
          primary_reason.c_str(), preflight.checked_pose_count);
        last_low_speed_static_wall_preflight_log_signature_ = signature;
        last_low_speed_static_wall_preflight_log_sec_ = now_sec;
      }
    } else {
      last_low_speed_static_wall_preflight_log_signature_.clear();
    }

    if (!update_last_target) {
      return candidate;
    }

    candidate = gap_planner->plan_stopped_vehicle_local_path(
      *model, ref_wp_id, N, lb, ub, now_sec, cfg.v2x_behavior, true,
      candidate.pass_side_sign);
    preflight = evaluate_gap_plan_static_wall_preflight(ref_wp_id, candidate);
    if (!preflight.feasible) {
      candidate.feasible = false;
      candidate.target_velocity_limit =
        std::max(0.0, cfg.v2x_gap.no_gap_target_velocity);
      candidate.reject_reason = "static wall commit preflight: " + preflight.reason;
      candidate.reject_gate = "static-wall-commit-preflight";
    }
    return candidate;
  }

  void set_v2x_race_session_active(const bool active, const double now_sec)
  {
    if (v2x_race_session_active_ == active) {
      return;
    }

    v2x_race_session_active_ = active;
    v2x_behavior_state = V2XBehaviorState::Cruise;
    v2x_behavior_state_initialized = false;
    last_v2x_behavior_state_change_sec = now_sec;
    last_v2x_behavior_debug_log_sec_ = std::numeric_limits<double>::quiet_NaN();
    low_speed_avoidance_stall_since_sec_ = std::numeric_limits<double>::quiet_NaN();
    low_speed_avoidance_stall_last_update_sec_ = std::numeric_limits<double>::quiet_NaN();
    low_speed_avoidance_stall_cooldown_until_sec_ = now_sec;
    front_hazard_hold_until_sec_ = now_sec;
    front_hazard_hold_target_id_.clear();
    start_grid_stop_suppressed_ = false;
    start_grid_emergency_override_logged_ = false;
    start_grid_initial_target_id_.reset();
    start_grid_breakout_target_id_.reset();
    start_grid_breakout_side_sign_ = 0;
    reset_start_grid_dynamic_decision();
    reset_low_speed_stopped_confirmation();
    reset_dynamic_obstacle_lateral_escape_runtime();
    last_published_overtake_execution_generation_ = 0U;
    last_low_speed_static_wall_preflight_log_sec_ =
      std::numeric_limits<double>::quiet_NaN();
    last_low_speed_static_wall_preflight_log_signature_.clear();
    v2x_course_progress_tracks_.clear();
    overtake_locked_target_ey_.reset();
    overtake_locked_side_sign_ = 0;
    mpcc_lite_shadow_last_evaluation_sec_ =
      -std::numeric_limits<double>::infinity();
    mpcc_lite_shadow_last_feasible_sec_ =
      -std::numeric_limits<double>::infinity();
    mpcc_lite_shadow_last_log_sec_ =
      -std::numeric_limits<double>::infinity();
    mpcc_lite_shadow_last_feasible_resolution_.reset();
    mpcc_frenet_dp_last_path_distances_.clear();
    mpcc_frenet_dp_last_lateral_path_.clear();
    mpcc_frenet_dp_last_target_id_.clear();
    mpcc_frenet_dp_last_side_sign_ = 0;
    mpcc_frenet_dp_last_tactical_strategy_ =
      overtake_core::FrenetDpTacticalStrategy::Legacy;
    mpcc_frenet_dp_last_feasible_sec_ =
      -std::numeric_limits<double>::infinity();
    mpcc_lite_cross_side_pending_sign_ = 0;
    mpcc_lite_cross_side_pending_since_sec_ =
      std::numeric_limits<double>::quiet_NaN();
    mpcc_lite_shadow_last_feasible_target_id_.clear();
    mpcc_lite_shadow_last_feasible_generation_ = 0U;
    mpcc_lite_shadow_last_feasible_phase_ = OvertakeLinePhase::Idle;
    mpcc_lite_shadow_last_feasible_side_sign_ = 0;
    mpcc_lite_shadow_last_logged_best_ =
      overtake_core::MpccLiteShadowBranch::None;
    mpcc_lite_shadow_last_logged_active_ =
      overtake_core::MpccLiteShadowBranch::None;
    mpcc_lite_shadow_last_logged_agreement_ = false;
    mpcc_lite_shadow_last_logged_hold_ = false;
    overtake_entry_speed_.reset();
    overtake_entry_speed_candidate_id_.clear();
    overtake_entry_speed_candidate_side_sign_ = 0;
    overtake_entry_speed_candidate_closing_speed_ =
      std::numeric_limits<double>::quiet_NaN();
    overtake_entry_speed_ready_since_sec_ = std::numeric_limits<double>::quiet_NaN();
    overtake_entry_prearm_last_validated_sec_ =
      -std::numeric_limits<double>::infinity();
    overtake_entry_prearm_start_sec_ = std::numeric_limits<double>::quiet_NaN();
    overtake_entry_prearm_last_update_sec_ = std::numeric_limits<double>::quiet_NaN();
    overtake_entry_prearm_traveled_m_ = 0.0;
    overtake_entry_prearm_cooldown_until_sec_ = now_sec;
    overtake_engagement_target_id_.clear();
    overtake_engagement_last_relevant_sec_ =
      -std::numeric_limits<double>::infinity();
    overtake_solver_recovery_active_ = false;
    overtake_solver_reentry_blocked_ = false;
    overtake_solver_recovery_success_count_ = 0;
    overtake_solver_cooldown_until_sec_ = now_sec;
    overtake_solver_cooldown_logged_ = false;
    overtake_curve_cooldown_until_sec_ = now_sec;
    overtake_line_side_retry_blocks_ = {};
    completed_overtake_target_block_ = CompletedOvertakeTargetBlock{};
    last_overtake_line_debug_log_sec_ = std::numeric_limits<double>::quiet_NaN();
    reset_osqp_history();
    reset_overtake_line_state(
      now_sec, active ? "AWSIM race session started" : "AWSIM race session inactive");
    if (gap_planner != nullptr) {
      gap_planner->reset_low_speed_targets();
    }
    last_v2x_behavior_output_ = V2XBehaviorOutput{};
    RCLCPP_INFO(
      rclcpp::get_logger("mpc_controller"),
      "V2X race session changed: active=%d; behavior, pass line, and watchdog reset",
      active ? 1 : 0);
  }

  start_grid_grace::Transition arm_start_grid_grace(const double start_sec)
  {
    return start_grid_grace_guard_.arm(start_sec);
  }

  start_grid_grace::Transition prepare_start_grid_grace()
  {
    return start_grid_grace_guard_.prepare();
  }

  start_grid_grace::Transition clear_start_grid_grace()
  {
    const auto transition = start_grid_grace_guard_.clear();
    if (transition == start_grid_grace::Transition::Cleared) {
      start_grid_stop_suppressed_ = false;
      start_grid_emergency_override_logged_ = false;
      start_grid_initial_target_id_.reset();
      start_grid_breakout_target_id_.reset();
      start_grid_breakout_side_sign_ = 0;
      reset_start_grid_dynamic_decision();
    }
    return transition;
  }

  bool start_grid_ready_rollout_active() const noexcept
  {
    return start_grid_grace_guard_.phase() == start_grid_grace::Phase::Prepared;
  }

  void reset_control_history(const double steering)
  {
    reset_osqp_history();
    previous_steering = std::isfinite(steering) ?
      clip(steering, -std::abs(cfg.delta_max), std::abs(cfg.delta_max)) : 0.0;
    current_control = Eigen::VectorXd::Zero(2 * std::max(0, cfg.N));
    for (int index = 0; index < cfg.N; ++index) {
      current_control[2 * index + 1] = previous_steering;
    }
    current_prediction.first.clear();
    current_prediction.second.clear();
    last_problem_context_.reset();
    last_solution_contract_.reset();
    last_solution_is_retained_ = false;
    last_published_canonical_intent_ = mpcc_contract::ControlIntent::Unknown;
    last_published_authority_intent_ = mpcc_contract::ControlIntent::Unknown;
    retained_execution_identity_was_selected_ = false;
    retained_execution_identity_last_sequence_ = 0U;
    last_rate_resolved_serialized_predecessor_.reset();
    failure_fallback_speed_ = 0.0;
    infeasibility_counter = 0;
    overtake_infeasibility_counter_ = 0;
    last_control_was_fallback_ = true;
    stage_corridor_mpc_constraints_was_active_ = false;
    stage_corridor_mpc_target_bound_was_active_ = false;
    stage_corridor_mpc_target_bound_solver_suppressed_was_active_ = false;
    stage_corridor_target_bound_candidate_since_sec_ =
      std::numeric_limits<double>::quiet_NaN();
    stage_corridor_target_bound_suppressed_until_sec_ =
      -std::numeric_limits<double>::infinity();
    stage_corridor_mpc_constraints_last_log_sec_ =
      -std::numeric_limits<double>::infinity();
  }

  void synchronize_wall_handoff_hold_control(
    const Eigen::Vector2d & published_control,
    const std::string & admission_reason)
  {
    if (!published_control.allFinite()) {
      return;
    }
    previous_steering = clip(
      published_control[1], -std::abs(cfg.delta_max), std::abs(cfg.delta_max));
    current_control = Eigen::VectorXd::Zero(2 * std::max(0, cfg.N));
    for (int index = 0; index < cfg.N; ++index) {
      current_control[2 * index] = std::max(0.0, published_control[0]);
      current_control[2 * index + 1] = previous_steering;
    }
    // Keep current_prediction intact until the final decision log consumes
    // the rejected physical evidence. Only the control warm start is replaced.
    last_control_resolution_reason_ =
      "wall-handoff-hold/" + admission_reason;
  }

  bool request_dynamic_escape_wall_replan(
    const std::string & reason, const double now_sec)
  {
    const bool live_escape =
      last_v2x_behavior_output_.dynamic_obstacle_lateral_escape_active;
    const std::string target_id = live_escape ?
      last_v2x_behavior_output_.dynamic_obstacle_cruise_target_id : std::string{};
    const int side_sign = live_escape ?
      last_v2x_behavior_output_.dynamic_obstacle_lateral_escape_side_sign : 0;
    if (target_id.empty() || (side_sign != -1 && side_sign != 1)) {
      return false;
    }

    clear_dynamic_obstacle_lateral_escape_tracking_qualification();
    const auto backoff = dynamic_obstacle_lateral_escape_solver_backoff_.record_failure(
      target_id, side_sign, now_sec,
      cfg.v2x_behavior.dynamic_obstacle_lateral_escape_solver_quarantine_sec,
      cfg.v2x_behavior.dynamic_obstacle_lateral_escape_solver_backoff_max_sec,
      cfg.v2x_behavior.dynamic_obstacle_lateral_escape_solver_backoff_reset_sec);
    if (gap_planner != nullptr) {
      gap_planner->reset_low_speed_targets();
    }
    RCLCPP_WARN(
      rclcpp::get_logger("mpc_controller"),
      "Dynamic escape wall replan requested: target=%s, side=%d, "
      "failures=%d, backoff=%.3f s, reason=%s",
      target_id.c_str(), side_sign, backoff.consecutive_failures,
      backoff.hold_sec, reason.c_str());
    return true;
  }

  bool request_active_overtake_wall_replan(
    const std::string & reason, const double now_sec,
    const std::uint64_t decision_id,
    const overtake_orchestrator::ExecutedSolutionWallAction requested_action =
    overtake_orchestrator::ExecutedSolutionWallAction::DynamicReplan)
  {
    const bool active_pass_execution =
      overtake_line_state_.phase == OvertakeLinePhase::ShiftOut ||
      overtake_line_state_.phase == OvertakeLinePhase::Pass;
    const bool returning =
      overtake_line_state_.phase == OvertakeLinePhase::Return;
    if (
      (!active_pass_execution && !returning) ||
      !overtake_line_state_.mission_path_frozen ||
      current_overtake_mission_invalidated())
    {
      return false;
    }

    const auto previous_phase = overtake_line_state_.phase;
    const std::uint64_t rejected_generation =
      overtake_line_state_.mission_generation;
    const bool generation_command_published =
      overtake_execution_command_published(rejected_generation);
    const std::string target_id = overtake_line_state_.target_vehicle_id;
    const int pass_side_sign = overtake_line_state_.pass_side_sign;
    bool failed_side_retry_block_armed = false;
    bool alternate_side_search_allowed = false;
    const bool rollback_untravelled_entry =
      active_pass_execution && previous_phase == OvertakeLinePhase::ShiftOut &&
      requested_action ==
      overtake_orchestrator::ExecutedSolutionWallAction::EntryRollback;
    if (active_pass_execution) {
      arm_overtake_line_side_retry_block(
        pass_side_sign, target_id, now_sec, reason,
        overtake_core::OvertakeSideRetryFailureClass::PhysicalOrCommittedFailure);
      failed_side_retry_block_armed = is_overtake_line_side_retry_blocked(
        pass_side_sign, target_id, now_sec);
    }
    invalidate_current_overtake_mission(reason);
    clear_last_feasible_maneuver_cache("active wall path rejected");
    // Reject both cached and in-flight tactical worker results produced from
    // the wall-invalidated context.  A later worker may still evaluate both
    // sides in shadow mode, but live authority applies the side retry block.
    invalidate_mpcc_lite_async_results();
    solved_mpcc_execution_trajectory_.reset();
    last_physically_validated_mpcc_execution_trajectory_.reset();
    // DynamicMissionWait normally preserves a recent DP prefix across a soft
    // target-side replan. A physical wall rejection is different: that exact
    // prefix is the rejected evidence and must never remain lateral authority.
    overtake_line_state_.mission_frenet_dp_execution_active = false;
    overtake_line_state_.mission_frenet_dp_side_sign = 0;
    overtake_line_state_.mission_frenet_dp_execution_traveled_m = 0.0;
    overtake_line_state_.mission_frenet_dp_path_distances_m.clear();
    overtake_line_state_.mission_frenet_dp_lateral_path_m.clear();
    overtake_line_state_.mission_frenet_dp_execution_authority_was_active = false;
    overtake_line_state_.mission_frenet_dp_execution_authority_runtime_was_active = false;
    overtake_line_state_.mission_frenet_dp_last_runtime_validation_sec =
      -std::numeric_limits<double>::infinity();
    overtake_line_state_.mission_runtime_wall_escape_prefix_active = false;
    if (gap_planner != nullptr) {
      gap_planner->reset_low_speed_targets();
    }

    if (active_pass_execution) {
      const auto & line_cfg = cfg.v2x_behavior.overtake_line;
      const auto & behavior_output = last_v2x_behavior_output_;
      const bool before_no_return =
        !overtake_line_state_.opponent_side_replan_no_return_latched &&
        !overtake_line_state_.mission_cross_side_transition_committed &&
        behavior_output.overtake_commit_stage ==
        overtake_core::PassCommitStage::ShiftCommitted &&
        std::isfinite(behavior_output.locked_target_longitudinal) &&
        behavior_output.locked_target_longitudinal + kEps >=
        line_cfg.opponent_side_replan_no_return_front_distance;
      const bool replacement_count_available =
        !overtake_line_state_.mission_cross_side_transition_committed &&
        overtake_line_state_.opponent_side_replan_count <
        line_cfg.opponent_side_replan_max_count;
      alternate_side_search_allowed = rollback_untravelled_entry ||
        (before_no_return && replacement_count_available);
      if (rollback_untravelled_entry) {
        // No command from this Mission has been published.  Do not create a
        // synthetic FollowPrepare episode or preserve lateral authority from
        // the rejected path; return directly to fresh side selection while
        // the failed side retry block prevents immediate reselection.
        transition_overtake_line_phase(
          OvertakeLinePhase::Idle, now_sec, model->spatial_state.e_y,
          pass_side_sign, "executed solution wall entry rollback: " + reason);
      } else {
        overtake_line_state_.dynamic_mission_wait_active = true;
        overtake_line_state_.dynamic_mission_wait_trigger_reason = reason;
        overtake_line_state_.dynamic_mission_wait_cross_side_lease_active =
          alternate_side_search_allowed;
        overtake_line_state_.dynamic_mission_wait_bounded_escape_at_entry = false;
        overtake_line_state_.dynamic_mission_wait_terminal_budget_abort = false;
        overtake_line_state_.dynamic_mission_wait_rear_clear_extension_logged = false;
        overtake_line_state_.dynamic_mission_wait_best_target_longitudinal_m =
          std::isfinite(behavior_output.locked_target_longitudinal) ?
          behavior_output.locked_target_longitudinal :
          std::numeric_limits<double>::infinity();
        overtake_line_state_.dynamic_mission_wait_last_progress_sec =
          std::isfinite(behavior_output.locked_target_longitudinal) ?
          now_sec : std::numeric_limits<double>::quiet_NaN();
        overtake_line_state_.opponent_side_replan_last_evaluation_sec =
          -std::numeric_limits<double>::infinity();
        transition_overtake_line_phase(
          OvertakeLinePhase::FollowPrepare, now_sec, model->spatial_state.e_y,
          pass_side_sign, "physical wall path rejected: " + reason,
          FollowPrepareCause::DynamicMissionWait);
      }
    } else {
      // A Return path no longer has an opponent-side Mission to replace. Let
      // the existing Recovery planner build a fresh wall-aware rejoin instead
      // of retaining the rejected return trajectory.
      transition_overtake_line_phase(
        OvertakeLinePhase::Recovery, now_sec, model->spatial_state.e_y,
        pass_side_sign, "physical Return wall path rejected: " + reason);
    }
    last_control_resolution_reason_ =
      "active-wall-path-replan/" + reason;
    RCLCPP_WARN(
      rclcpp::get_logger("mpc_controller"),
      "Overtake wall path invalidated: decision=%lu, target=%s, "
      "generation=%lu, phase=%s, side=%d, action=%s, "
      "command_published=%d, failed_side_retry_block=%d, "
      "alternate_search=%d, reason=%s, wp_id=%d",
      static_cast<unsigned long>(decision_id), target_id.c_str(),
      static_cast<unsigned long>(rejected_generation),
      to_string(previous_phase), pass_side_sign,
      rollback_untravelled_entry ? "entry-rollback" :
      (active_pass_execution ? "dynamic-replan" : "recovery-replan"),
      generation_command_published ? 1 : 0,
      failed_side_retry_block_armed ? 1 : 0,
      alternate_side_search_allowed ? 1 : 0,
      reason.c_str(), model != nullptr ? model->wp_id : -1);
    return true;
  }

  bool overtake_execution_command_published(
    const std::uint64_t mission_generation) const noexcept
  {
    return mission_generation > 0U &&
      last_published_overtake_execution_generation_ == mission_generation;
  }

  void mark_overtake_execution_command_published(
    const std::uint64_t mission_generation) noexcept
  {
    if (mission_generation > 0U) {
      last_published_overtake_execution_generation_ = mission_generation;
    }
  }

  bool last_control_was_fallback() const
  {
    return last_control_was_fallback_;
  }

  bool executed_solution_wall_hold_active() const noexcept
  {
    return executed_solution_wall_hold_active_;
  }

  int consecutive_solver_failure_count() const noexcept
  {
    return infeasibility_counter;
  }

  std::uint64_t last_control_decision_id() const noexcept
  {
    return active_control_decision_id_;
  }

  void record_rate_resolved_publication_successor(
    const std::uint64_t decision_id,
    const double final_target_speed_mps,
    const double final_acceleration_mps2,
    const double final_physical_steering_rad,
    const double final_wire_steering_rad, const double now_sec,
    const bool normal_successor_allowed)
  {
    std::optional<RateResolvedSerializedPredecessor> predecessor;
    if (
      current_physical_steering_state_.has_value() &&
      mpcc_contract::physical_steering_matches_serialized_actuation(
        final_physical_steering_rad, final_wire_steering_rad,
        cfg.steering_tire_angle_gain_var))
    {
      const auto previous_input =
        mpcc_rate_resolved_problem::resolve_serialized_previous_input(
        mpcc_rate_resolved_problem::SerializedPreviousInputRequest{
          final_acceleration_mps2, final_target_speed_mps,
          current_physical_steering_state_->committed_steering_rad,
          final_physical_steering_rad,
          current_physical_steering_state_->committed_command_control_age_sec});
      if (previous_input.has_value() && decision_id != 0U &&
        std::isfinite(now_sec))
      {
        predecessor = RateResolvedSerializedPredecessor{
          decision_id, now_sec, final_physical_steering_rad,
          final_wire_steering_rad, previous_input.value()};
        last_rate_resolved_serialized_predecessor_ = predecessor;
      }
    }
    if (!pending_rate_resolved_publication_successor_.has_value()) {
      return;
    }
    auto pending = std::move(
      pending_rate_resolved_publication_successor_.value());
    pending_rate_resolved_publication_successor_.reset();
    const bool preentry_pending = pending.preentry_draft.has_value();
    const char * publication_reject_reason = nullptr;
    if (!normal_successor_allowed) {
      publication_reject_reason = "normal-successor-disallowed";
    } else if (!predecessor.has_value()) {
      publication_reject_reason = "serialized-predecessor-unavailable";
    } else if (pending.decision_id != decision_id) {
      publication_reject_reason = "decision-mismatch";
    } else if (!std::isfinite(now_sec) || now_sec < pending.snapshot_sec) {
      publication_reject_reason = "publication-time-invalid";
    } else if (!mpcc_contract::physical_steering_matches_serialized_actuation(
        final_physical_steering_rad, final_wire_steering_rad,
        cfg.steering_tire_angle_gain_var))
    {
      publication_reject_reason = "serialized-steering-mismatch";
    }
    if (
      publication_reject_reason != nullptr)
    {
      ++rate_resolved_track_cruise_shadow_telemetry_window_.
        submission_reject_count;
      if (preentry_pending) {
        const auto & draft = pending.preentry_draft.value();
        RCLCPP_WARN(
          rclcpp::get_logger("mpc_controller"),
          "Gate A lifecycle: boundary=publication, admitted=0, reason=%s, "
          "kind=%s, decision=%lu/%lu, target=%s, side=%d, tactical=%lu, "
          "generation=%lu, authority=observation-only",
          publication_reject_reason,
          rate_resolved_intent_transition_kind_name(draft.kind),
          static_cast<unsigned long>(pending.decision_id),
          static_cast<unsigned long>(decision_id), draft.target_id.c_str(),
          draft.selected_side_sign,
          static_cast<unsigned long>(draft.tactical_source_sequence),
          static_cast<unsigned long>(draft.prospective_mission_generation));
      }
      return;
    }
    if (pending.normal_draft.has_value()) {
      const auto bound_submission =
        bind_rate_resolved_track_cruise_submission(
        pending.normal_draft.value(), predecessor.value());
      if (bound_submission.has_value()) {
        static_cast<void>(submit_rate_resolved_track_cruise_shadow(
            pending.source_problem, bound_submission.value(),
            pending.snapshot_sec));
      } else {
        ++rate_resolved_track_cruise_shadow_telemetry_window_.
          submission_reject_count;
      }
    }
    if (pending.preentry_draft.has_value()) {
      const auto & draft = pending.preentry_draft.value();
      const auto kind = draft.kind;
      const auto tactical_source_sequence = draft.tactical_source_sequence;
      const auto prospective_mission_generation =
        draft.prospective_mission_generation;
      const auto selected_side_sign = draft.selected_side_sign;
      const auto target_id = draft.target_id;
      const bool admitted = submit_rate_resolved_preentry_execution_shadow(
        std::move(pending.preentry_draft.value()), predecessor.value(), now_sec);
      RCLCPP_INFO(
        rclcpp::get_logger("mpc_controller"),
        "Gate A lifecycle: boundary=publication, admitted=%d, reason=%s, "
        "kind=%s, decision=%lu, target=%s, side=%d, tactical=%lu, "
        "generation=%lu, authority=observation-only",
        admitted ? 1 : 0, admitted ? "worker-submitted" : "worker-rejected",
        rate_resolved_intent_transition_kind_name(kind),
        static_cast<unsigned long>(decision_id), target_id.c_str(),
        selected_side_sign,
        static_cast<unsigned long>(tactical_source_sequence),
        static_cast<unsigned long>(prospective_mission_generation));
    }
  }

  void observe_published_certified_stop_successor_join(
    const RateResolvedRetainedShadowEvaluation & current,
    const std::uint64_t decision_id)
  {
    if (!published_certified_stop_successor_observation_.has_value()) {
      return;
    }
    auto published = std::move(
      published_certified_stop_successor_observation_.value());
    published_certified_stop_successor_observation_.reset();
    const auto result = stop_successor_observation::evaluate(
      published,
      stop_successor_observation::CurrentControlOrigin{
        decision_id, current.current_control_state_available,
        current.observation_origin_sec, current.control_origin_sec,
        current.control_pose.x_m, current.control_pose.y_m,
        current.control_pose.yaw_rad, current.control_origin_speed_mps,
        current.current_steering_rad, current.current_time_steering_rad,
        current.current_response_steering_rad,
        current.previous_published_steering_rad});
    const auto & evidence = published.evidence;
    certified_stop_successor_telemetry_window_.record(
      evidence.source_intent, result);
    if (
      !std::isfinite(current.observation_origin_sec) ||
      !std::isfinite(certified_stop_successor_telemetry_last_log_sec_))
    {
      certified_stop_successor_telemetry_last_log_sec_ =
        current.observation_origin_sec;
      return;
    }
    const double window_sec = current.observation_origin_sec -
      certified_stop_successor_telemetry_last_log_sec_;
    if (window_sec < 1.0) {
      return;
    }
    const auto & window = certified_stop_successor_telemetry_window_;
    const auto reason = [&window](const stop_successor_observation::Reason value) {
        return window.reason_count[static_cast<std::size_t>(value)];
      };
    const auto intent = [&window](const mpcc_contract::ControlIntent value) {
        return window.sampled_intent_count[static_cast<std::size_t>(value)];
      };
    std::ostringstream summary;
    summary << std::fixed << std::setprecision(6)
            << "Certified Stop successor join summary: window=" << window_sec
            << "s, sampled="
            << reason(stop_successor_observation::Reason::Sampled)
            << ", rejected=" << window.rejected_count()
            << "[identity="
            << reason(stop_successor_observation::Reason::InvalidIdentity)
            << ",shape="
            << reason(stop_successor_observation::Reason::InvalidShape)
            << ",state="
            << reason(stop_successor_observation::Reason::InvalidCurrentState)
            << ",time="
            << reason(stop_successor_observation::Reason::TimeOutsideSuccessor)
            << "], intents=track:" << intent(mpcc_contract::ControlIntent::Track)
            << "/cruise:" << intent(mpcc_contract::ControlIntent::Cruise)
            << "/follow:" << intent(mpcc_contract::ControlIntent::Follow)
            << "/shiftout:" << intent(mpcc_contract::ControlIntent::ShiftOut)
            << "/pass:" << intent(mpcc_contract::ControlIntent::Pass)
            << "/return:" << intent(mpcc_contract::ControlIntent::Return)
            << "/rejoin:" << intent(mpcc_contract::ControlIntent::Rejoin)
            << ", error_mean/max=position:"
            << window.position.mean_absolute() << "/"
            << window.position.maximum_absolute
            << "m,yaw:" << window.yaw.mean_absolute() << "/"
            << window.yaw.maximum_absolute
            << "rad,speed:" << window.speed.mean_absolute() << "/"
            << window.speed.maximum_absolute
            << "mps,steering_command_origin:"
            << window.command_origin_steering.mean_absolute() << "/"
            << window.command_origin_steering.maximum_absolute
            << ",steering_current_time:"
            << window.current_time_steering.mean_absolute() << "/"
            << window.current_time_steering.maximum_absolute
            << ",steering_response_origin:"
            << window.response_origin_steering.mean_absolute() << "/"
            << window.response_origin_steering.maximum_absolute
            << ",steering_previous_published:"
            << window.previous_published_steering.mean_absolute() << "/"
            << window.previous_published_steering.maximum_absolute
            << "rad, authority=observation-only";
    if (window.rejected_count() > 0U) {
      RCLCPP_WARN(
        rclcpp::get_logger("mpc_controller"), "%s", summary.str().c_str());
    } else {
      RCLCPP_INFO(
        rclcpp::get_logger("mpc_controller"), "%s", summary.str().c_str());
    }
    certified_stop_successor_telemetry_window_ = {};
    certified_stop_successor_telemetry_last_log_sec_ =
      current.observation_origin_sec;
  }
  OvertakeSiblingAdoptionLiveState
  current_overtake_sibling_adoption_live_state() const
  {
    OvertakeSiblingAdoptionLiveState state;
    state.active_execution =
      overtake_line_state_.phase == OvertakeLinePhase::ShiftOut ||
      overtake_line_state_.phase == OvertakeLinePhase::Pass;
    state.intent =
      overtake_line_state_.phase == OvertakeLinePhase::ShiftOut ?
      mpcc_contract::ControlIntent::ShiftOut :
      overtake_line_state_.phase == OvertakeLinePhase::Pass ?
      mpcc_contract::ControlIntent::Pass :
      mpcc_contract::ControlIntent::Unknown;
    state.target_id = overtake_line_state_.target_vehicle_id;
    state.mission_generation = overtake_line_state_.mission_generation;
    state.side_sign = overtake_line_state_.pass_side_sign;
    const bool target_continuous =
      last_v2x_behavior_output_.locked_target_seen &&
      !last_v2x_behavior_output_.locked_target_position_jump &&
      !last_v2x_behavior_output_.locked_target_course_progress_rejected &&
      last_v2x_behavior_output_.target_vehicle_id == state.target_id;
    state.hard_fault =
      !target_continuous ||
      last_v2x_behavior_output_.front_risk_level ==
      FrontRiskLevel::EmergencyBrake ||
      overtake_solver_recovery_active_ ||
      last_v2x_behavior_output_.overtake_forbidden_wp;
    state.selected_homotopy_established =
      last_v2x_behavior_output_.locked_target_current_lateral_clear &&
      std::isfinite(
      last_v2x_behavior_output_.locked_target_relative_lateral) &&
      (state.side_sign == -1 || state.side_sign == 1) &&
      state.side_sign *
      last_v2x_behavior_output_.locked_target_relative_lateral < -kEps;
    state.before_no_return =
      !overtake_line_state_.opponent_side_replan_no_return_latched &&
      !overtake_line_state_.mission_cross_side_transition_committed &&
      last_v2x_behavior_output_.overtake_commit_stage ==
      overtake_core::PassCommitStage::ShiftCommitted &&
      std::isfinite(last_v2x_behavior_output_.locked_target_longitudinal) &&
      last_v2x_behavior_output_.locked_target_longitudinal + kEps >=
      cfg.v2x_behavior.overtake_line.
      opponent_side_replan_no_return_front_distance;
    state.replacement_budget_available =
      !overtake_line_state_.mission_cross_side_transition_committed &&
      overtake_line_state_.opponent_side_replan_count <
      cfg.v2x_behavior.overtake_line.opponent_side_replan_max_count;
    return state;
  }

  void invalidate_published_stop_lattice_observation() noexcept
  {
    rate_resolved_stop_lattice_published_source_identity_.reset();
    rate_resolved_stop_lattice_current_world_alternate_plan_.reset();
    if (rate_resolved_stop_lattice_shadow_worker_ != nullptr) {
      static_cast<void>(
        rate_resolved_stop_lattice_shadow_worker_->
        invalidate_pending_and_running());
    }
  }

  void update_published_stop_lattice_observation(
    const CanonicalNormalPendingActuation & published)
  {
    const bool stop_observation_intent =
      published.command.intent == mpcc_contract::ControlIntent::ShiftOut ||
      published.command.intent == mpcc_contract::ControlIntent::Pass;
    if (!stop_observation_intent) {
      invalidate_published_stop_lattice_observation();
      return;
    }
    if (
      rate_resolved_stop_lattice_shadow_worker_ == nullptr ||
      rate_resolved_stop_lattice_shadow_solver_context_ == nullptr ||
      rate_resolved_stop_lattice_shadow_mailbox_ == nullptr ||
      published.selected_plan == nullptr ||
      published.selected_plan->execution_artifact == nullptr)
    {
      invalidate_published_stop_lattice_observation();
      static rclcpp::Clock source_reject_clock{RCL_STEADY_TIME};
      RCLCPP_ERROR_THROTTLE(
        rclcpp::get_logger("mpc_controller"), source_reject_clock, 1000,
        "Published Stop lattice source rejected: decision=%lu, intent=%s, "
        "plan=%d, artifact=%d, source=%d, authority=shadow, selected=0",
        static_cast<unsigned long>(published.decision_id),
        mpcc_contract::to_string(published.command.intent),
        published.selected_plan != nullptr ? 1 : 0,
        published.selected_plan != nullptr &&
        published.selected_plan->execution_artifact != nullptr ? 1 : 0,
        published.selected_plan != nullptr &&
        published.selected_plan->solver_source_snapshot != nullptr ? 1 : 0);
      return;
    }

    const auto & identity =
      published.selected_plan->execution_artifact->identity;
    if (
      rate_resolved_stop_lattice_published_source_identity_.has_value() &&
      rate_resolved_artifact::same_identity(
        rate_resolved_stop_lattice_published_source_identity_.value(),
        identity))
    {
      return;
    }

    const bool same_tactical_scope =
      rate_resolved_stop_lattice_published_source_identity_.has_value() &&
      rate_resolved_stop_lattice_shadow::same_tactical_stop_scope(
        rate_resolved_stop_lattice_published_source_identity_.value(),
        identity);
    if (!same_tactical_scope) {
      rate_resolved_stop_lattice_current_world_alternate_plan_.reset();
      static_cast<void>(
        rate_resolved_stop_lattice_shadow_worker_->
        invalidate_pending_and_running());
    }
    // Publication owns only the live tactical scope.  Stop candidate
    // generation is submitted beside each immutable current-world normal
    // snapshot; deriving it here from a possibly old selected normal epoch
    // was the temporal mismatch that made a physically feasible Stop appear
    // steering-unreachable at current-world join.
    rate_resolved_stop_lattice_published_source_identity_ = identity;
  }

  void record_canonical_normal_final_command(
    const std::uint64_t decision_id, const double final_target_speed_mps,
    const double final_acceleration_mps2, const double final_steering_rad,
    const double now_sec)
  {
    if (!pending_canonical_normal_actuation_.has_value()) {
      return;
    }
    const auto pending = pending_canonical_normal_actuation_.value();
    pending_canonical_normal_actuation_.reset();
    auto & window = canonical_normal_final_actuation_telemetry_window_;
    if (pending.decision_id != decision_id) {
      ++window.rejected_count;
      ++window.identity_rejected_count;
      return;
    }
    if (!mpcc_contract::canonical_normal_command_matches_serialized_actuation(
        pending.command, final_target_speed_mps, final_acceleration_mps2,
        final_steering_rad, cfg.steering_tire_angle_gain_var))
    {
      ++window.rejected_count;
      ++window.serialized_actuation_rejected_count;
      window.last_rejected_decision_id = decision_id;
      window.last_rejected_solution_id = pending.command.solution_id;
      window.last_rejected_plan_sequence =
        pending.selected_plan != nullptr &&
        pending.selected_plan->execution_artifact != nullptr ?
        pending.selected_plan->execution_artifact->identity.sequence : 0U;
      window.last_rejected_expected_speed_mps =
        pending.command.predicted_speed_mps;
      window.last_rejected_final_speed_mps = final_target_speed_mps;
      window.last_rejected_expected_acceleration_mps2 =
        pending.command.acceleration_mps2;
      window.last_rejected_final_acceleration_mps2 = final_acceleration_mps2;
      window.last_rejected_expected_physical_steering_rad =
        pending.command.steering_tire_angle_rad;
      window.last_rejected_final_wire_steering_rad = final_steering_rad;
      return;
    }

    if (pending.record_published_bundle_source) {
      if (
        rate_resolved_track_cruise_certified_plan_store_ == nullptr ||
        pending.selected_plan == nullptr ||
        rate_resolved_track_cruise_certified_plan_store_->
        record_published_bundle_source(
          pending.selected_plan, pending.selected_sibling_plan, decision_id,
          pending.first_published_control_origin_sec,
          pending.first_published_artifact_elapsed_sec) !=
        rate_resolved_certified::StoreReason::Accepted)
      {
        ++window.rejected_count;
        ++window.bundle_source_record_rejected_count;
        RCLCPP_ERROR(
          rclcpp::get_logger("mpc_controller"),
          "Canonical MPCC published Bundle source record rejected: "
          "decision=%lu, solution=%lu",
          static_cast<unsigned long>(decision_id),
          static_cast<unsigned long>(pending.command.solution_id));
        return;
      }
    } else if (pending.promote_to_executed) {
      if (
        rate_resolved_track_cruise_certified_plan_store_ == nullptr ||
        pending.selected_plan == nullptr ||
        rate_resolved_track_cruise_certified_plan_store_->mark_executed(
          pending.selected_plan, pending.selected_sibling_plan, decision_id,
          pending.first_published_control_origin_sec,
          pending.first_published_artifact_elapsed_sec) !=
        rate_resolved_certified::StoreReason::Accepted)
      {
        ++window.rejected_count;
        ++window.execution_promotion_rejected_count;
        RCLCPP_ERROR(
          rclcpp::get_logger("mpc_controller"),
          "Canonical MPCC published candidate execution promotion rejected: "
          "decision=%lu, solution=%lu",
          static_cast<unsigned long>(decision_id),
          static_cast<unsigned long>(pending.command.solution_id));
        return;
      }
    }
    if (
      !pending.record_published_bundle_source &&
      rate_resolved_track_cruise_certified_plan_store_ != nullptr)
    {
      rate_resolved_track_cruise_certified_plan_store_->
      supersede_published_bundle_source(decision_id);
    }

    update_published_stop_lattice_observation(pending);

    if (pending.overtake_sibling_adoption_token.has_value()) {
      const auto & token = pending.overtake_sibling_adoption_token.value();
      const auto live = current_overtake_sibling_adoption_live_state();
      if (!overtake_sibling_adoption::token_matches_live_state(
          token, live.intent, live.target_id, live.mission_generation,
          live.side_sign, live.active_execution,
          live.selected_homotopy_established, live.before_no_return,
          live.replacement_budget_available, live.hard_fault))
      {
        if (rate_resolved_track_cruise_certified_plan_store_ != nullptr) {
          rate_resolved_track_cruise_certified_plan_store_->
          supersede_published_bundle_source(decision_id);
        }
        RCLCPP_ERROR(
          rclcpp::get_logger("mpc_controller"),
          "Published sibling Bundle could not commit tactical authority: "
          "target=%s, generation=%lu, side=%d->%d, sequence=%lu, phase=%s",
          token.target_id.c_str(),
          static_cast<unsigned long>(token.mission_generation),
          token.previous_side_sign, token.adopted_side_sign,
          static_cast<unsigned long>(token.source_sequence),
          to_string(overtake_line_state_.phase));
      } else {
        // The exact opposite-side Bundle has now crossed the only command
        // publisher. Retire all geometry owned by the rejected frozen
        // Mission, while preserving encounter identity, phase and cumulative
        // completion budgets. Future geometry is rebuilt from current world.
        overtake_line_state_.pass_side_sign = token.adopted_side_sign;
        overtake_locked_side_sign_ = token.adopted_side_sign;
        overtake_line_state_.opponent_side_replan_count += 1;
        overtake_line_state_.mission_cross_side_transition_committed = true;
        overtake_line_state_.opponent_side_replan_no_return_latched = true;
        overtake_line_state_.opponent_side_replan_pending_sign = 0;
        overtake_line_state_.opponent_side_replan_pending_since_sec =
          std::numeric_limits<double>::quiet_NaN();
        overtake_line_state_.opponent_side_replan_last_evaluation_sec = now_sec;
        overtake_line_state_.stateless_sibling_authority_active = true;
        overtake_line_state_.stateless_sibling_source_sequence =
          token.source_sequence;
        overtake_line_state_.stateless_sibling_source_generation =
          token.mission_generation;
        overtake_line_state_.mission_plan.reset();
        overtake_line_state_.mission_path_frozen = false;
        overtake_line_state_.fixed_pass_corridor_goal_ey.reset();
        overtake_line_state_.mission_frenet_dp_execution_active = false;
        overtake_line_state_.mission_frenet_dp_side_sign = 0;
        overtake_line_state_.mission_frenet_dp_execution_traveled_m = 0.0;
        overtake_line_state_.mission_frenet_dp_path_distances_m.clear();
        overtake_line_state_.mission_frenet_dp_lateral_path_m.clear();
        overtake_line_state_.mission_frenet_dp_execution_authority_was_active =
          false;
        overtake_line_state_.
          mission_frenet_dp_execution_authority_runtime_was_active = false;
        overtake_line_state_.mission_pass_lateral_replan_active = false;
        overtake_line_state_.mission_return_preflight_reference_active = false;
        overtake_line_state_.mission_return_preflight_path_distances_m.clear();
        overtake_line_state_.mission_return_preflight_lateral_path_m.clear();
        overtake_line_state_.mission_outer_strategy_committed = false;
        overtake_line_state_.mission_outer_transition_pending = false;
        overtake_line_state_.mission_outer_transition_side_sign = 0;
        overtake_line_state_.mission_runtime_wall_escape_prefix_active = false;
        clear_last_feasible_maneuver_cache(
          "published stateless sibling authority adopted");
        RCLCPP_WARN(
          rclcpp::get_logger("mpc_controller"),
          "Published stateless sibling Bundle adopted: target=%s, "
          "generation=%lu, side=%d->%d, sequence=%lu, phase=%s",
          token.target_id.c_str(),
          static_cast<unsigned long>(token.mission_generation),
          token.previous_side_sign, token.adopted_side_sign,
          static_cast<unsigned long>(token.source_sequence),
          to_string(overtake_line_state_.phase));
      }
    }

    // The tactical proposal and solver selection are not publication events.
    // Update this ledger only after the exact serialized command has joined
    // and any newly certified candidate has become the executed plan.
    last_published_canonical_intent_ = pending.command.intent;
    if (pending.certified_stop_successor.has_value()) {
      const auto & evidence = pending.certified_stop_successor.value();
      if (
        evidence.source_decision_id == decision_id &&
        evidence.solution_id == pending.command.solution_id &&
        evidence.problem_fingerprint ==
        pending.command.problem_fingerprint &&
        evidence.source_intent == pending.command.intent &&
        std::isfinite(evidence.control_origin_sec) &&
        !evidence.exact_trajectory.elapsed_time_sec.empty() &&
        evidence.actuation_samples.size() ==
        evidence.exact_trajectory.elapsed_time_sec.size() &&
        evidence.world_prediction.first.size() ==
        evidence.exact_trajectory.elapsed_time_sec.size() &&
        evidence.world_prediction.second.size() ==
        evidence.exact_trajectory.elapsed_time_sec.size() &&
        evidence.world_yaw_rad.size() ==
        evidence.exact_trajectory.elapsed_time_sec.size() &&
        evidence.publisher_interval_sample_count > 0U &&
        evidence.publisher_interval_sample_count <=
        evidence.actuation_samples.size())
      {
        published_certified_stop_successor_observation_ =
          stop_successor_observation::Published{evidence, now_sec};
      } else {
        published_certified_stop_successor_observation_.reset();
        RCLCPP_ERROR(
          rclcpp::get_logger("mpc_controller"),
          "Certified Stop successor publication evidence rejected: "
          "decision=%lu, solution=%lu, intent=%s, authority=observation-only",
          static_cast<unsigned long>(decision_id),
          static_cast<unsigned long>(pending.command.solution_id),
          mpcc_contract::to_string(pending.command.intent));
      }
    } else {
      published_certified_stop_successor_observation_.reset();
    }

    const double speed_difference_mps = std::abs(
      pending.command.predicted_speed_mps - final_target_speed_mps);
    const double acceleration_difference_mps2 = std::abs(
      pending.command.acceleration_mps2 - final_acceleration_mps2);
    const auto expected_wire_steering_rad =
      mpcc_contract::resolve_published_steering_tire_angle(
        pending.command.steering_tire_angle_rad,
        cfg.steering_tire_angle_gain_var);
    if (!expected_wire_steering_rad.has_value()) {
      ++window.rejected_count;
      ++window.serialized_actuation_rejected_count;
      return;
    }
    const double steering_difference_rad = std::abs(
      expected_wire_steering_rad.value() - final_steering_rad);
    ++window.joined_count;
    window.total_predicted_speed_vs_final_target_difference_mps +=
      speed_difference_mps;
    window.maximum_predicted_speed_vs_final_target_difference_mps = std::max(
      window.maximum_predicted_speed_vs_final_target_difference_mps,
      speed_difference_mps);
    window.total_optimized_acceleration_vs_final_difference_mps2 +=
      acceleration_difference_mps2;
    window.maximum_optimized_acceleration_vs_final_difference_mps2 = std::max(
      window.maximum_optimized_acceleration_vs_final_difference_mps2,
      acceleration_difference_mps2);
    window.total_serialized_steering_vs_final_difference_rad +=
      steering_difference_rad;
    window.maximum_serialized_steering_vs_final_difference_rad = std::max(
      window.maximum_serialized_steering_vs_final_difference_rad,
      steering_difference_rad);

    if (!std::isfinite(now_sec)) {
      return;
    }
    if (
      !std::isfinite(last_canonical_normal_final_actuation_log_sec_) ||
      now_sec < last_canonical_normal_final_actuation_log_sec_)
    {
      last_canonical_normal_final_actuation_log_sec_ = now_sec;
      return;
    }
    if (now_sec - last_canonical_normal_final_actuation_log_sec_ < 1.0) {
      return;
    }
    const double joined = static_cast<double>(
      std::max<std::uint64_t>(1U, window.joined_count));
    RCLCPP_INFO(
      rclcpp::get_logger("mpc_controller"),
      "Canonical MPCC production actuation join: joined=%zu, rejected=%zu, "
      "reject_reason=identity:%zu/serialized:%zu/promotion:%zu/"
      "bundle_source:%zu, "
      "predicted_speed_vs_final_target=%.3f/%.3f(avg/max)mps, "
      "optimized_acceleration_vs_final=%.3f/%.3f(avg/max)mps2, "
      "serialized_steering_vs_final=%.4f/%.4f(avg/max)rad, "
      "last_reject=decision:%lu/solution:%lu/plan:%lu/"
      "speed:%.9f/%.9f/acceleration:%.9f/%.9f/"
      "steering_physical:%.9f/wire:%.9f, "
      "authority=production, selected=1",
      static_cast<std::size_t>(window.joined_count),
      static_cast<std::size_t>(window.rejected_count),
      static_cast<std::size_t>(window.identity_rejected_count),
      static_cast<std::size_t>(
        window.serialized_actuation_rejected_count),
      static_cast<std::size_t>(
        window.execution_promotion_rejected_count),
      static_cast<std::size_t>(
        window.bundle_source_record_rejected_count),
      window.total_predicted_speed_vs_final_target_difference_mps / joined,
      window.maximum_predicted_speed_vs_final_target_difference_mps,
      window.total_optimized_acceleration_vs_final_difference_mps2 / joined,
      window.maximum_optimized_acceleration_vs_final_difference_mps2,
      window.total_serialized_steering_vs_final_difference_rad / joined,
      window.maximum_serialized_steering_vs_final_difference_rad,
      static_cast<unsigned long>(window.last_rejected_decision_id),
      static_cast<unsigned long>(window.last_rejected_solution_id),
      static_cast<unsigned long>(window.last_rejected_plan_sequence),
      window.last_rejected_expected_speed_mps,
      window.last_rejected_final_speed_mps,
      window.last_rejected_expected_acceleration_mps2,
      window.last_rejected_final_acceleration_mps2,
      window.last_rejected_expected_physical_steering_rad,
      window.last_rejected_final_wire_steering_rad);
    window = CanonicalNormalFinalActuationTelemetryWindow{};
    last_canonical_normal_final_actuation_log_sec_ = now_sec;
  }

  void record_final_published_authority(
    const mpcc_contract::ControlIntent authority_intent,
    const bool publication_overridden) noexcept
  {
    const bool normal_execution_interrupted =
      publication_overridden ||
      authority_intent == mpcc_contract::ControlIntent::Stop;
    if (
      normal_execution_interrupted &&
      rate_resolved_track_cruise_certified_plan_store_ != nullptr &&
      rate_resolved_track_cruise_certified_plan_store_->clear())
    {
      // PublishedPlan is an execution ledger, not a lease. Once another
      // authority crosses the publisher, elapsed wall time can no longer be
      // used to advance skipped normal controls. Keep the independently
      // certified candidate bank, but require its existing current-world join
      // before normal authority can return.
      RCLCPP_WARN(
        rclcpp::get_logger("mpc_controller"),
        "Canonical normal execution ledger interrupted: authority=%s, "
        "overridden=%d, action=discard-executed-clock/retain-candidates",
        mpcc_contract::to_string(authority_intent),
        publication_overridden ? 1 : 0);
    }
    if (publication_overridden) {
      invalidate_published_stop_lattice_observation();
      last_published_authority_intent_ =
        mpcc_contract::ControlIntent::Unknown;
      return;
    }
    if (
      mpcc_contract::canonical_normal_intent_supported(authority_intent) ||
      authority_intent == mpcc_contract::ControlIntent::Stop)
    {
      if (authority_intent == mpcc_contract::ControlIntent::Stop) {
        invalidate_published_stop_lattice_observation();
      }
      last_published_authority_intent_ = authority_intent;
      return;
    }
    invalidate_published_stop_lattice_observation();
    last_published_authority_intent_ =
      mpcc_contract::ControlIntent::Unknown;
  }

