  race_mpcc::TargetProvenance locked_target_provenance(
    const V2XBehaviorOutput & behavior) const
  {
    race_mpcc::TargetProvenance provenance;
    provenance.target_id = behavior.target_vehicle_id;
    provenance.source_stamp_sec = behavior.locked_target_source_stamp_sec;
    provenance.receipt_sec = behavior.locked_target_receipt_sec;
    provenance.course_progress_m = behavior.locked_target_course_progress_m;
    provenance.course_lateral_m = behavior.locked_target_lateral;
    provenance.observation_generation =
      behavior.locked_target_observation_generation;
    provenance.stage = race_mpcc::TargetProvenanceStage::Locked;
    provenance.valid =
      behavior.locked_target_seen &&
      !behavior.locked_target_course_progress_rejected &&
      !provenance.target_id.empty() &&
      std::isfinite(provenance.source_stamp_sec) &&
      std::isfinite(provenance.receipt_sec) &&
      std::isfinite(provenance.course_progress_m) &&
      std::isfinite(provenance.course_lateral_m) &&
      provenance.observation_generation > 0U;
    return provenance;
  }

  race_mpcc::TargetProvenance selected_target_provenance(
    const V2XBehaviorOutput & behavior) const
  {
    const auto locked = locked_target_provenance(behavior);
    if (locked.valid && locked.target_id == behavior.target_vehicle_id) {
      return locked;
    }
    if (
      behavior.target_observation_provenance.target_id ==
      behavior.target_vehicle_id)
    {
      return behavior.target_observation_provenance;
    }
    race_mpcc::TargetProvenance invalid;
    invalid.target_id = behavior.target_vehicle_id;
    return invalid;
  }

  mpc_stage_geometry::Geometry build_stage_geometry(
    const int tracking_waypoint, const std::size_t stage_count)
  {
    if (model == nullptr || model->reference_path == nullptr) {
      return mpc_stage_geometry::build({}, tracking_waypoint, stage_count, false);
    }
    const auto & waypoints = model->reference_path->waypoints;
    if (stage_geometry_path_cache_.size() != waypoints.size()) {
      stage_geometry_path_cache_.clear();
      stage_geometry_path_cache_.reserve(waypoints.size());
      for (const auto & waypoint : waypoints) {
        stage_geometry_path_cache_.push_back({waypoint.x, waypoint.y});
      }
    }
    return mpc_stage_geometry::build(
      stage_geometry_path_cache_, tracking_waypoint, stage_count,
      model->reference_path->circular);
  }

  race_mpcc::TargetProvenanceValidation validate_selected_target_provenance(
    const race_mpcc::TargetProvenance & expected,
    const V2XBehaviorOutput & current_behavior,
    const double elapsed_sec) const
  {
    const double bounded_elapsed_sec =
      std::isfinite(elapsed_sec) ? std::max(0.0, elapsed_sec) : 0.0;
    const double target_speed_mps =
      std::isfinite(current_behavior.locked_target_speed) ?
      std::max(0.0, current_behavior.locked_target_speed) :
      (std::isfinite(current_behavior.overtake_entry_target_speed) ?
      std::max(0.0, current_behavior.overtake_entry_target_speed) : 0.0);
    const bool path_available = model != nullptr && model->reference_path != nullptr;
    return race_mpcc::validate_target_provenance(
      race_mpcc::TargetProvenanceValidationRequest{
        expected,
        selected_target_provenance(current_behavior),
        path_available && model->reference_path->circular,
        path_available ? model->reference_path->length : 0.0,
        0.25,
        kV2XCourseProgressContinuityToleranceM +
        std::max(1.0, target_speed_mps) * bounded_elapsed_sec,
        std::max(
          0.25,
          std::max(
            0.0,
            cfg.v2x_behavior.overtake_line.
            mpcc_lite_same_side_max_lateral_adjustment))});
  }

  mpcc_contract::ControlIntent current_control_intent() const noexcept
  {
    if (!last_overtake_authority_trace_.has_value()) {
      return v2x_race_session_active_ ?
        mpcc_contract::ControlIntent::Cruise :
        mpcc_contract::ControlIntent::Track;
    }
    const auto resolution =
      overtake_orchestrator::resolve_canonical_control_intent(
      last_overtake_authority_trace_->request,
      last_overtake_authority_trace_->resolution);
    return resolution.valid ? resolution.intent :
      mpcc_contract::ControlIntent::Unknown;
  }

  static bool has_coherent_follow_front_observation(
    const V2XBehaviorOutput & behavior) noexcept
  {
    return
      behavior.has_front_vehicle &&
      std::isfinite(behavior.front_distance) &&
      behavior.front_distance >= 0.0 &&
      std::isfinite(behavior.front_speed) && behavior.front_speed >= 0.0 &&
      behavior.target_observation_provenance.valid &&
      behavior.target_observation_provenance.target_id ==
      behavior.target_vehicle_id;
  }

  mpcc_contract::MpccProblemContext make_problem_context(
    const MpcProblem & problem,
    const mpcc_contract::Formulation formulation,
    const std::optional<mpcc_contract::ControlIntent> intent_override =
    std::nullopt,
    const int horizon_steps_override = -1) const
  {
    mpcc_contract::MpccProblemContext context;
    context.decision_id = active_control_decision_id_;
    // The controller consumes one odometry/state observation per decision.
    // Keep that generation distinct from the independently updated V2X
    // obstacle observation below.
    context.observation_generation = active_control_decision_id_;
    context.intent = intent_override.value_or(current_control_intent());
    const bool encounter_identity_required =
      mpcc_contract::canonical_normal_intent_requires_target(context.intent);
    if (last_overtake_authority_trace_.has_value()) {
      context.intent_generation =
        last_overtake_authority_trace_->request.mission_generation;
    }
    if (
      encounter_identity_required &&
      last_overtake_authority_trace_.has_value())
    {
      context.target_id = last_overtake_authority_trace_->request.target_id;
    }
    if (mpcc_contract::canonical_normal_intent_requires_execution_side(
        context.intent))
    {
      context.execution_side_sign =
        problem.progress_execution_side_sign != 0 ?
        problem.progress_execution_side_sign :
        problem.dynamic_obstacle_lateral_escape_side_sign;
    }
    const auto provenance = selected_target_provenance(last_v2x_behavior_output_);
    if (
      encounter_identity_required && provenance.valid &&
      (context.target_id.empty() || provenance.target_id == context.target_id))
    {
      context.target_obstacle_generation = provenance.observation_generation;
      if (context.target_id.empty()) {
        context.target_id = provenance.target_id;
      }
    }
    context.dynamic_obstacle_constraint_active =
      problem.progress_execution_dynamic_obstacle_contract_active;
    if (context.dynamic_obstacle_constraint_active) {
      context.dynamic_obstacle_id = provenance.target_id;
      context.dynamic_obstacle_generation = provenance.observation_generation;
      context.dynamic_obstacle_side_sign =
        problem.progress_execution_dynamic_obstacle_side_sign;
    }
    context.formulation = formulation;
    return seal_problem_context_for_problem(
      problem, std::move(context), horizon_steps_override);
  }

  mpcc_contract::MpccProblemContext seal_problem_context_for_problem(
    const MpcProblem & problem,
    mpcc_contract::MpccProblemContext context,
    const int horizon_steps_override = -1) const
  {
    const auto formulation = context.formulation;
    context.fingerprint = 0U;
    context.state_schema_id.clear();
    context.input_schema_id.clear();
    context.bounds_schema_id.clear();
    context.cost_schema_id.clear();
    const bool progress_geometry_required =
      formulation ==
      mpcc_contract::Formulation::VelocitySteeringYawResponseProgress7State;
    const int effective_horizon_steps = horizon_steps_override >= 0 ?
      horizon_steps_override : problem.N;
    if (progress_geometry_required) {
      if (
        effective_horizon_steps <= 0 ||
        effective_horizon_steps > problem.N ||
        static_cast<std::size_t>(effective_horizon_steps) >
        problem.progress_stage_geometry.stages.size())
      {
        context.stage_geometry_id = 0U;
      } else if (effective_horizon_steps == problem.N) {
        context.stage_geometry_id = problem.progress_stage_geometry.fingerprint;
      } else {
        std::vector<mpcc_contract::StageGeometryIdentity> stages(
          problem.progress_stage_geometry.stages.begin(),
          problem.progress_stage_geometry.stages.begin() +
          effective_horizon_steps);
        context.stage_geometry_id = mpcc_contract::fingerprint_stage_geometry(
          problem.progress_stage_geometry.tracking_waypoint,
          problem.progress_stage_geometry.circular, stages);
      }
    } else {
      std::vector<mpcc_contract::StageGeometryIdentity> stages;
      stages.reserve(problem.stage_geometry.stages.size());
      for (const auto & stage : problem.stage_geometry.stages) {
        stages.push_back(mpcc_contract::StageGeometryIdentity{
          stage.transition_from_waypoint, stage.state_waypoint,
          stage.transition_distance_m, stage.cumulative_distance_m});
      }
      context.stage_geometry_id = mpcc_contract::fingerprint_stage_geometry(
        problem.stage_geometry.tracking_waypoint,
        problem.stage_geometry.circular, stages);
    }
    context.horizon_steps = static_cast<std::size_t>(
      std::max(0, effective_horizon_steps));
    switch (formulation) {
      case mpcc_contract::Formulation::VelocitySteeringYawResponseProgress7State:
        context.state_schema_id =
          "ey-elag-epsi-v-progress-steering-yaw-response-v2";
        context.input_schema_id =
          "accel-steering-rate-progress-rate-v1";
        context.bounds_schema_id =
          "progress-stage-wall-obstacle-steering-yaw-response-rate-v2";
        context.cost_schema_id =
          "velocity-steering-yaw-response-progress-v2";
        break;
      case mpcc_contract::Formulation::SolverDerivedBypass:
        context.state_schema_id = "retained-current-state-v1";
        context.input_schema_id = "speed-steering-v1";
        context.bounds_schema_id = "derived-hold-v1";
        context.cost_schema_id = "derived-bypass-v1";
        break;
      case mpcc_contract::Formulation::Unresolved:
        break;
      default:
        break;
    }
    return mpcc_contract::seal_problem_context(std::move(context));
  }

  void record_problem_context(
    const MpcProblem & problem,
    const mpcc_contract::Formulation formulation,
    const std::optional<mpcc_contract::ControlIntent> intent_override =
    std::nullopt)
  {
    last_problem_context_ = make_problem_context(
      problem, formulation, intent_override);
    last_solution_contract_.reset();
    last_solution_is_retained_ = false;
  }

  void record_solution_contract(
    const MpcProblem & problem,
    const mpcc_contract::Formulation formulation,
    const Eigen::VectorXd & primal,
    const double maximum_constraint_violation,
    const bool physical_wall_checked,
    const bool physical_wall_clear,
    const double now_sec)
  {
    record_problem_context(problem, formulation);
    if (solution_contract_sequence_ == std::numeric_limits<std::uint64_t>::max()) {
      solution_contract_sequence_ = 0U;
    }
    mpcc_contract::CertifiedMpccSolution solution;
    solution.solution_id = ++solution_contract_sequence_;
    solution.problem_fingerprint = last_problem_context_->fingerprint;
    solution.formulation = formulation;
    solution.solved = true;
    solution.finite = primal.allFinite();
    solution.constraints_satisfied =
      std::isfinite(maximum_constraint_violation) &&
      maximum_constraint_violation >= 0.0;
    solution.maximum_constraint_violation = maximum_constraint_violation;
    solution.physical.checked = physical_wall_checked;
    solution.physical.wall_clear = physical_wall_clear;
    solution.physical.obstacles_clear =
      problem.lateral_bounds_contract_valid && solution.constraints_satisfied;
    solution.physical.minimum_wall_clearance_m =
      problem.progress_execution_context_active ?
      problem.progress_execution_physical_wall_clearance_m :
      std::numeric_limits<double>::quiet_NaN();
    solution.prediction_stage_count =
      static_cast<std::size_t>(std::max(0, problem.N));
    const double horizon_sec =
      model != nullptr && std::isfinite(model->Ts) ?
      std::max(0.0, model->Ts) * static_cast<double>(std::max(0, problem.N)) :
      0.0;
    solution.valid_until_sec = now_sec + horizon_sec;
    last_solution_contract_ = std::move(solution);
  }

